var e={entries:JSON.parse(`{"assign":{"short":"Legt den Wert rechts in den Namen links.","simple":"Wie eine neue Zahl auf eine beschriftete Kiste schreiben: Was vorher drin war, ist weg.","deep":"Zuweisung, keine Frage: Vergleichen geht mit <code>==</code>. In einer Deklaration wie <code>uint8_t r = 0;</code> gibt das <code>=</code> der Variable ihren ersten Wert (Initialisierung)."},"arithmetic":{"short":"Addieren, Subtrahieren und Dividieren, wie am Taschenrechner.","simple":"Schulmathe, mit einer Überraschung: Teilst du zwei ganze Zahlen, fällt der Rest weg, also ist <code>7 / 2</code> gleich <code>3</code>.","deep":"Ganzzahldivision schneidet Richtung null ab; schreib <code>7 / 2.0f</code>, um <code>3.5</code> zu bekommen. Kleine Typen wie <code>uint8_t</code> werden vor dem Rechnen zu <code>int</code> erweitert, also kann <code>pos * 3</code> erst beim Zurückspeichern überlaufen."},"modulo":{"short":"Der Rest nach dem Teilen: <code>7 % 3</code> ist <code>1</code>.","simple":"Wie ein Zifferblatt: Zählst du über 12 hinaus, fängst du wieder bei 1 an. Darum passt <code>%</code> perfekt zu allem, was im Kreis läuft.","deep":"Funktioniert nur mit ganzen Zahlen (für Floats nimm <code>fmodf</code>). Ist die linke Seite negativ, wird auch das Ergebnis negativ, also ist <code>-1 % 6</code> gleich <code>-1</code>, nicht <code>5</code>."},"compound-assign":{"short":"Kurzschreibweise, die eine Variable mit ihrem eigenen Wert aktualisiert: <code>x += 5</code> heißt <code>x = x + 5</code>.","simple":"Wie ein Glas auffüllen: Du leerst es nicht und füllst neu, du gibst nur etwas dazu.","deep":"Die linke Seite wird einmal ausgewertet, was wichtig ist, wenn dort etwas wie <code>buf_[i++]</code> steht. Das Ergebnis wird zurück in den Typ der Variable umgewandelt, also läuft ein <code>uint8_t</code> still über 255 hinaus."},"increment":{"short":"Zählt eins zu einer Variable dazu (<code>++</code>) oder zieht eins ab (<code>--</code>).","simple":"Ein Strichzähler zum Klicken: ein Klick, eins mehr.","deep":"<code>i++</code> gibt den alten Wert zurück und zählt dann eins hoch; <code>++i</code> zählt zuerst. In einer einzelnen <code>for</code>-Schleife verhalten sich beide gleich. Ein vorzeichenloser <code>uint8_t hue</code> springt von 255 auf 0, worauf sich der Regenbogen in Lektion 01 verlässt."},"compare":{"short":"Vergleicht zwei Werte und antwortet <code>true</code> oder <code>false</code>; nach einem Typnamen halten &lt; &gt; stattdessen einen Typ.","simple":"Fragen mit Ja/Nein-Antwort: Ist es gleich? Ist es kleiner? Beachte das doppelte <code>==</code>: Ein einzelnes <code>=</code> würde den Wert ändern, statt zu fragen.","deep":"Vergleichst du Vorzeichenbehaftetes mit Vorzeichenlosem, wird die vorzeichenbehaftete Seite in vorzeichenlos umgewandelt, also ist <code>-1 &lt; 1u</code> falsch; der Compiler warnt davor. In <code>std::vector&lt;Card&gt;</code> oder <code>static_cast&lt;int&gt;</code> sind die spitzen Klammern Template-Klammern, keine Vergleiche."},"logic":{"short":"Verknüpft Ja/Nein-Antworten: <code>&amp;&amp;</code> heißt und, <code>||</code> heißt oder, <code>!</code> heißt nicht.","simple":"„Wenn es regnet <b>und</b> ich draußen bin, spann den Schirm auf.“ <code>!</code> dreht eine Antwort um: es regnet nicht.","deep":"Kurzschluss: <code>a &amp;&amp; b</code> schaut nie auf <code>b</code>, wenn <code>a</code> falsch ist, darum ist <code>queue_ &amp;&amp; xQueueReceive(queue_, ...)</code> mit einer Null-Queue sicher. Nach einem Typ (<code>T &amp;&amp;</code>) steht das doppelte Und-Zeichen stattdessen für eine verschiebbare Referenz."},"ternary":{"short":"Ein einzeiliges if/else, das einen Wert wählt: <code>test ? this : that</code>.","simple":"„Ist das HUD an? Dann sag ‚on‘, sonst sag ‚off‘.“ Eine Frage mit zwei möglichen Antworten.","deep":"Beide Zweige müssen sich in einen gemeinsamen Typ umwandeln lassen. Nur der gewählte Zweig wird ausgewertet, also kannst du damit sicher eine Division oder einen Pointer absichern."},"shift":{"short":"Schiebt die Bits einer Zahl nach links oder rechts; ein Schritt links verdoppelt sie, ein Schritt rechts halbiert sie.","simple":"Wie die Ziffern einer Zahl auf einer Reihe Lichtschalter verschieben: Alles rutscht weiter, und hinten kommt eine neue 0 herein.","deep":"Dient zum Ein- und Auspacken von Bytes: <code>(r &amp; 0xF8) &lt;&lt; 8</code> setzt Rot in die obersten 5 Bits einer RGB565-Farbe. Um die Breite des Typs oder mehr zu schieben, ist undefiniertes Verhalten."},"bit-ops":{"short":"Arbeiten an den einzelnen Bits einer Zahl: <code>|</code> setzt Bits, <code>^</code> kippt sie, <code>~</code> kehrt alle um.","simple":"Stell dir eine Zahl als Reihe aus 8, 16 oder 32 Lichtschaltern vor. Diese Operatoren kippen gewählte Schalter, ohne die anderen anzufassen.","deep":"<code>flags |= bit</code> schaltet ein Bit an, <code>flags &amp;= ~bit</code> schaltet es aus, <code>flags ^= bit</code> kippt es. Register-Treiber wie unser MFRC522 leben davon. ArduinoJson nutzt <code>|</code> auch für einen Standardwert: <code>in[\\"type\\"] | \\"\\"</code>."},"scope":{"short":"Greift in einen Namespace, eine Klasse oder ein Enum, um einen Namen zu finden: <code>std::min</code> ist das <code>min</code>, das in <code>std</code> wohnt.","simple":"Wie eine Adresse: <i>London::Baker Street</i>. Zwei Straßen können denselben Namen tragen, solange sie in verschiedenen Städten liegen.","deep":"Der Scope-Resolution-Operator. <code>Button::Event::Click</code> geht zwei Ebenen tief; ein führendes <code>::</code> (wie in <code>::ble::activity()</code>) startet im globalen Namespace, sodass ein lokaler Name es nie verdecken kann."},"arrow":{"short":"Greift auf ein Mitglied dessen zu, worauf ein Pointer zeigt: <code>p->x</code> ist dasselbe wie <code>(*p).x</code>.","simple":"Ein Punkt (<code>.</code>) spricht ein Objekt an, das du in der Hand hältst; der Pfeil spricht ein Objekt an, von dem du nur die Adresse hast.","deep":"Mitgliedszugriff über einen Pointer. Web-Handler bekommen <code>AsyncWebServerRequest *req</code>, also heißt es <code>req->send(...)</code>. Einem <code>nullptr</code> zu folgen, lässt den ESP32 mit einer LoadProhibited- oder StoreProhibited-Panic abstürzen, darum werden Pointer vorher geprüft."},"maths":{"short":"Mathe-Helfer aus der C-Bibliothek: Sinus, Kosinus, Quadratwurzel, Runden, Betrag und Freunde.","simple":"Die wissenschaftlichen Tasten eines Taschenrechners, fertig im Code nutzbar. Winkel sind im Bogenmaß: Eine volle Drehung sind etwa 6,283.","deep":"Die <code>f</code>-Versionen (<code>sinf</code>, <code>sqrtf</code>) arbeiten mit <code>float</code>, das die Hardware-FPU des ESP32-S3 schnell verarbeitet; die <code>double</code>-Versionen laufen in Software und sind mehrmals langsamer. <code>lroundf</code> rundet auf die nächste ganze Zahl."},"snprintf":{"short":"Baut aus einem Muster und Werten einen Text, in eine Kiste fester Größe.","simple":"Ein Lückentext: <code>\\"%d/%d\\"</code> hat zwei Lücken, und die Zahlen, die du übergibst, füllen sie der Reihe nach.","deep":"<code>snprintf(buf, sizeof(buf), fmt, ...)</code> schreibt nie über den Puffer hinaus und beendet den Text immer mit <code>'\\\\0'</code>; zu langer Text wird abgeschnitten. Dieselben <code>%</code>-Codes wie bei <code>Serial.printf</code>: <code>%d</code> int, <code>%u</code> unsigned, <code>%lu</code> unsigned long, <code>%.1f</code> float, <code>%s</code> Text, <code>%02X</code> hex."},"void":{"short":"Heißt „nichts“: Eine <code>void</code>-Funktion erledigt ihren Job, gibt aber keinen Wert zurück.","simple":"Wie eine Türklingel: Du drückst, und etwas passiert, aber du bekommst nichts in die Hand.","deep":"Als Rückgabetyp heißt es: kein Ergebnis. <code>void *</code> ist ein Pointer auf Speicher unbekannten Typs, wie im <code>void *arg</code>, das FreeRTOS-Tasks und Interrupt-Handler bekommen; vor der Nutzung muss er zurückgecastet werden."},"bool":{"short":"Ein Ja/Nein-Wert: entweder <code>true</code> oder <code>false</code>.","simple":"Ein Lichtschalter: an oder aus, nichts dazwischen.","deep":"Braucht ein Byte. Zahlen und Pointer werden automatisch zu <code>bool</code> (null und <code>nullptr</code> sind falsch), darum funktioniert <code>if (buf_)</code>. Arduinos <code>boolean</code> ist derselbe Typ."},"true-false":{"short":"Die zwei Werte, die ein <code>bool</code> halten kann.","simple":"Ja und nein, so geschrieben, wie der Compiler es versteht.","deep":"Schlüsselwörter vom Typ <code>bool</code>; in Zahlen umgewandelt werden sie 1 und 0. FreeRTOS nutzt für dieselbe Idee sein eigenes <code>pdTRUE</code>/<code>pdFALSE</code>."},"int":{"short":"Eine ganze Zahl, die negativ sein kann, der Alltagsstandard zum Zählen.","simple":"Eine Kiste für ganze Zahlen wie -3, 0 oder 42. Keine Brüche erlaubt.","deep":"Auf dem ESP32 hat ein <code>int</code> 32 Bit: etwa -2,1 Milliarden bis +2,1 Milliarden. Seine Größe unterscheidet sich je nach Chip (16 Bit auf einem Arduino Uno), darum bevorzugt Hardware-Code oft <code>int32_t</code> und Verwandte, die ihre Größe nennen."},"long":{"short":"Ein Ganzzahltyp, der mindestens so groß ist wie <code>int</code>; auf dem ESP32 haben beide 32 Bit.","simple":"Noch eine Kiste für ganze Zahlen. Auf diesem Chip fasst sie genau, was ein <code>int</code> fasst.","deep":"<code>long</code> hat 32 Bit auf dem Xtensa-ESP32 und <code>long long</code> hat 64. <code>millis()</code> gibt <code>unsigned long</code> zurück, also braucht die Ausgabe <code>%lu</code>; der Code castet oft mit <code>static_cast&lt;unsigned long&gt;</code>, damit das exakt passt."},"unsigned":{"short":"Eine ganze Zahl, die nicht unter null gehen kann und dafür doppelt so hoch reicht.","simple":"Wie der Kilometerzähler im Auto: Er zählt nur von 0 aufwärts und rollt nach der letzten Ziffer zurück auf 0.","deep":"Vorzeichenlose Mathematik läuft über, statt zu überlaufen: <code>0u - 1</code> ist der größte Wert. Dieser Umlauf ist genau der Grund, warum <code>now - last >= interval</code> weiter funktioniert, wenn <code>millis()</code> überläuft. <code>unsigned(x)</code> ist ein schneller Cast, praktisch für <code>%u</code> in printf."},"float":{"short":"Eine Zahl mit Dezimalpunkt, wie <code>3.14</code> oder <code>-0.5</code>.","simple":"Ein Lineal mit feinen Strichen: gut zum Messen, aber winzige Rundungsfehler schleichen sich ein, also teste zwei Floats nie auf exakte Gleichheit.","deep":"32 Bit, etwa 7 signifikante Stellen. Der ESP32-S3 hat eine FPU für einfache Genauigkeit, also ist <code>float</code>-Mathe schnell; schreib Konstanten als <code>0.5f</code>, damit der Compiler nicht auf langsames <code>double</code> umschaltet."},"double":{"short":"Eine Dezimalzahl mit etwa doppelter Genauigkeit wie <code>float</code>.","simple":"Dasselbe Lineal wie bei <code>float</code>, mit noch feineren Strichen, aber auf diesem Chip langsamer abzulesen.","deep":"64 Bit, etwa 15 signifikante Stellen. Die FPU des ESP32-S3 kann nur einfache Genauigkeit, also läuft <code>double</code> in Software: in Ordnung für eine gelegentliche Rechnung, zu langsam für jedes Pixel oder jeden Audio-Sample."},"char":{"short":"Ein Zeichen Text, als kleine Zahl gespeichert; <code>const char *</code> ist ein ganzes Stück Text.","simple":"Ein einzelnes Buchstabenplättchen aus einem Wortspiel. Reih Plättchen auf, schließ mit einem unsichtbaren Stopp-Plättchen <code>'\\\\0'</code> ab, und du hast ein Wort.","deep":"Ein Byte. Ein C-String ist ein Array aus <code>char</code>, das mit <code>'\\\\0'</code> endet; <code>char text[32]</code> fasst bis zu 31 Buchstaben. <code>\\"hello\\"</code> ist ein <code>const char *</code> auf Text im Flash, während <code>'h'</code> (einfache Anführungszeichen) ein einzelnes <code>char</code> ist."},"size-t":{"short":"Eine vorzeichenlose ganze Zahl für Größen und Anzahlen von Dingen im Speicher.","simple":"Die Zahl auf dem Maßband für Speicher: wie viele Bytes, wie viele Elemente. Sie kann nie negativ sein.","deep":"32 Bit auf dem ESP32, der Typ, den <code>sizeof</code> liefert und <code>malloc</code> nimmt. Gib ihn nach einem Cast mit <code>%u</code> aus, oder mit <code>%zu</code>."},"uint8-t":{"short":"Eine ganze Zahl von 0 bis 255: genau ein Byte.","simple":"Die kleinste Kiste: ein Byte, acht An/Aus-Schalter. Perfekt für einen Farbkanal, eine Pin-Nummer oder eine Helligkeit.","deep":"<code>u</code> = unsigned, <code>int</code>, <code>8</code> Bit, <code>_t</code> = ein Typ. Definiert in <code>&lt;stdint.h&gt;</code>, damit seine Größe auf jedem Chip gleich ist. Arduinos <code>byte</code> ist derselbe Typ. Über 255 hinaus springt er auf 0."},"uint16-t":{"short":"Eine ganze Zahl von 0 bis 65 535: zwei Bytes.","simple":"Eine Kiste doppelt so groß wie ein Byte. Jede Bildschirmfarbe in diesen Labs passt hinein.","deep":"Vorzeichenlos, 16 Bit. Der ST7789 spricht RGB565: 5 Bit Rot, 6 Grün, 5 Blau, gepackt in ein <code>uint16_t</code>. Wird auch für BLE-Handles und 16-Bit-UUIDs genutzt."},"uint32-t":{"short":"Eine ganze Zahl von 0 bis etwa 4,29 Milliarden: vier Bytes.","simple":"Eine große Kiste für große Zählwerte, etwa die Millisekunden seit dem Start des Boards.","deep":"Vorzeichenlos, 32 Bit: die natürliche Wortgröße des ESP32, also sind Lesen und Schreiben einzelne Befehle. Zeiten von <code>millis()</code> leben darin und laufen nach etwa 49,7 Tagen über."},"uint64-t":{"short":"Eine riesige ganze Zahl, 0 bis etwa 18 Trillionen: acht Bytes.","simple":"Eine Kiste, die so groß ist, dass sie praktisch nie voll wird. Die 48-Bit-MAC-Adresse des Chips passt locker hinein.","deep":"Vorzeichenlos, 64 Bit. Auf einer 32-Bit-CPU braucht jede Operation ein paar Befehle, und eine Zahl zu lesen, die sich Interrupt und Hauptcode teilen, ist kein einzelner Schritt, darum halten die Labs geteilte Zeitstempel bei 32 Bit."},"int8-t":{"short":"Eine kleine ganze Zahl von -128 bis 127: ein Byte, das negativ sein kann.","simple":"Eine Ein-Byte-Kiste mit Platz für ein Minuszeichen. Gut für Dinge wie die WLAN-Signalstärke in dBm.","deep":"Vorzeichenbehaftet, 8 Bit, Zweierkomplement. BLE-Sendeleistung und RSSI-Werte werden als <code>int8_t</code> gemeldet."},"int16-t":{"short":"Eine ganze Zahl von -32 768 bis 32 767: zwei Bytes, die negativ sein können.","simple":"Eine Zwei-Byte-Kiste mit Minuszeichen. Bildschirmkoordinaten nutzen sie, damit Formen knapp außerhalb des Rands starten können.","deep":"Vorzeichenbehaftet, 16 Bit. Adafruit GFX nimmt <code>int16_t</code> für x, y, Breite und Höhe, und 16-Bit-Audio-Samples vom Mikrofon sind ebenfalls <code>int16_t</code>."},"int32-t":{"short":"Eine ganze Zahl von etwa -2,1 Milliarden bis +2,1 Milliarden: vier Bytes, die negativ sein können.","simple":"Dieselbe Kiste wie <code>int</code> auf diesem Chip, aber ihr Name verspricht die Größe auf jedem Chip.","deep":"Vorzeichenbehaftet, 32 Bit. Das INMP441-Mikrofon sendet 24-Bit-Samples in 32-Bit-I2S-Slots, die als <code>int32_t</code> gelesen und dann nach unten geschoben werden."},"int64-t":{"short":"Eine riesige ganze Zahl, die negativ sein kann: acht Bytes.","simple":"Eine Kiste, die nie ausgeht, für Uhren, die Mikrosekunden zählen.","deep":"Vorzeichenbehaftet, 64 Bit. <code>esp_timer_get_time()</code> gibt <code>int64_t</code> Mikrosekunden seit dem Boot zurück, was etwa 292 000 Jahre bis zum Überlauf bräuchte."},"string-class":{"short":"Arduinos Texttyp: ein Stück Text, das wachsen, schrumpfen und durchsucht werden kann.","simple":"Eine dehnbare Notizbuchseite für Wörter: ergänzen, Stücke herausschneiden, ein Wort suchen, ohne selbst Buchstaben zu zählen.","deep":"Hält seine Buchstaben auf dem Heap (kurze inline), also wirbelt wiederholtes <code>+</code> in einer vielbeschäftigten Schleife den Speicher auf. Die Labs nutzen <code>String</code> für serielle Befehle und Web-Antworten und feste <code>char</code>-Arrays, wo Tempo oder Interrupts zählen. <code>String(42)</code> macht aus einer Zahl Text."},"auto":{"short":"Lässt den Compiler den Typ aus dem Wert ableiten, den du ihm gibst.","simple":"Wie „leg es in eine Kiste passender Größe“, statt die Kiste zu benennen.","deep":"Der Typ steht trotzdem beim Kompilieren fest, er ist nicht dynamisch. <code>auto *self = static_cast&lt;Button *&gt;(arg);</code> erspart dir, <code>Button</code> zweimal zu schreiben; <code>auto</code> ist auch, wie Lambdas gespeichert werden, da ihr Typ keinen Namen hat."},"nullptr":{"short":"Ein Pointer, der auf nichts zeigt.","simple":"Ein leeres Adressschild: Es gibt kein Haus zu besuchen, also prüf, bevor du gehst.","deep":"Die typsichere Null-Pointer-Konstante (C++11), die <code>NULL</code> und <code>0</code> ersetzt. Allokationsfunktionen wie <code>heap_caps_malloc</code> geben ihn bei Fehlschlag zurück, und viele ESP-IDF-Aufrufe nehmen ihn für „brauch ich nicht“."},"if":{"short":"Führt den nächsten Block nur aus, wenn der Test in Klammern wahr ist.","simple":"„Wenn es regnet, nimm einen Schirm.“ Regnet es nicht, wird der Schirm-Schritt übersprungen.","deep":"Die Bedingung wird in <code>bool</code> umgewandelt, also funktionieren Zahlen und Pointer direkt. Eine Deklaration im Test (<code>if (DeserializationError e = deserializeJson(...))</code>) hält die Variable im if."},"else":{"short":"Der andere Weg: läuft, wenn der <code>if</code>-Test falsch war.","simple":"„…sonst setz die Sonnenbrille auf.“ Genau einer der zwei Wege passiert.","deep":"<code>else if</code> ist nur ein <code>else</code>, dessen Block ein weiteres <code>if</code> ist, also werden Ketten von oben nach unten geprüft und stoppen beim ersten wahren Test."},"for":{"short":"Wiederholt einen Block eine gezählte Anzahl von Malen oder einmal für jedes Element einer Liste.","simple":"„Für jedes der 6 Bytes: gib es aus.“ Bei 0 anfangen, prüfen, ob du fertig bist, die Arbeit tun, hochzählen, wiederholen.","deep":"<code>for (init; test; step)</code>. Die Bereichsform <code>for (const auto &amp;card : cards)</code> besucht jedes Element eines Arrays oder Containers ohne Index."},"while":{"short":"Wiederholt einen Block, solange sein Test wahr bleibt.","simple":"„Solange Briefe im Briefkasten sind, nimm einen heraus.“ Ist er leer, hör auf.","deep":"Der Test läuft vor jeder Runde, also kann der Rumpf null Mal laufen. Ein <code>while</code>, das in <code>loop()</code> nie endet, lässt den Rest des Programms verhungern; die Labs lesen Eingaben mit <code>while (Serial.available())</code>, das endet, sobald der Puffer leer ist."},"do-while":{"short":"Wie <code>while</code>, aber der Block läuft immer mindestens einmal vor dem Test.","simple":"Die Suppe probieren, dann entscheiden, ob sie mehr Salz braucht. Du probierst immer zuerst.","deep":"Der Test steht nach dem Rumpf und braucht ein Semikolon: <code>do { ... } while (cond);</code>. Praktisch für „wähl einen Zufallswert, bis er gut ist“."},"switch":{"short":"Wählt einen von mehreren Wegen, indem ein Wert mit festen Optionen verglichen wird.","simple":"Ein Aufzug-Tableau: Drück die 3, und du fährst in Stockwerk 3. Jeder <code>case</code> ist ein Knopf.","deep":"Funktioniert mit ganzen Zahlen und Enums, nicht mit Text. Die Ausführung rutscht in den nächsten Case durch, außer du nutzt <code>break</code> oder <code>return</code>. Bei einer <code>enum class</code> warnt der Compiler vor vergessenen Cases."},"case":{"short":"Eine Wahl innerhalb eines <code>switch</code>: der Code, der läuft, wenn der Wert passt.","simple":"Ein Knopf auf dem Aufzug-Tableau, mit dem Stockwerk daneben.","deep":"Das Label muss eine Konstante zur Kompilierzeit sein. Mehrere Labels können sich einen Rumpf teilen, wenn du sie stapelst; ein Rumpf ohne <code>break</code> läuft in den nächsten Case weiter."},"default":{"short":"In einem <code>switch</code> der Weg, der genommen wird, wenn kein <code>case</code> gepasst hat.","simple":"Der „alles andere“-Knopf.","deep":"Optional und kann irgendwo im Switch stehen. In einer Klasse heißt <code>= default</code> etwas anderes: den Compiler bitten, diesen Konstruktor oder Operator für dich zu schreiben."},"break":{"short":"Verlässt sofort die aktuelle Schleife oder den <code>switch</code>.","simple":"Ein Notausgang: Hör auf, im Kreis zu laufen, und mach nach der Schleife weiter.","deep":"Verlässt nur die innerste Schleife oder den innersten Switch. In einem Switch, der in einer Schleife steckt, verlässt <code>break</code> den Switch, nicht die Schleife."},"continue":{"short":"Überspringt den Rest dieser Schleifenrunde und startet die nächste.","simple":"„Dieser Brief ist nicht für mich: leg ihn beiseite und öffne den nächsten.“","deep":"In einer <code>for</code>-Schleife läuft der Schritt (<code>i++</code>) trotzdem vor dem nächsten Test. Wird oft genutzt, um schlechte Daten früh zu überspringen, statt <code>if</code>s zu verschachteln."},"return":{"short":"Beendet die Funktion jetzt und gibt optional einen Wert an den Aufrufer zurück.","simple":"Die fertigen Hausaufgaben abgeben: Die Arbeit ist getan, hier ist die Antwort.","deep":"In einer <code>void</code>-Funktion verlässt ein nacktes <code>return;</code> sie einfach früher, ein üblicher Weg, bei schlechter Eingabe auszusteigen (eine Guard Clause). Lokale Variablen werden auf dem Weg nach draußen zerstört, so entsperrt <code>std::lock_guard</code>."},"setup-loop":{"short":"Jedes Arduino-Programm hat diese zwei: <code>setup()</code> läuft einmal beim Einschalten, <code>loop()</code> läuft dann für immer.","simple":"Einen Laden öffnen: <code>setup()</code> schließt einmal die Tür auf und macht das Licht an; <code>loop()</code> bedient Kunde um Kunde bis Ladenschluss (Strom aus).","deep":"Das <code>main</code> des Arduino-Core startet einen FreeRTOS-Task („loopTask“, Core 1, standardmäßig 8 KB Stack), der <code>setup()</code> und dann immer wieder <code>loop()</code> aufruft. Halt <code>loop()</code> schnell und nicht blockierend: Prüf <code>millis()</code> statt langer <code>delay()</code>s. Das <code>lab.loop()</code> eines Labs ist die eigene Arbeit der Shell pro Runde."},"lambda":{"short":"Eine kleine Funktion, direkt dort geschrieben, wo sie gebraucht wird, oft an eine andere Funktion übergeben, die sie später aufruft.","simple":"Ein Haftzettel mit Anweisungen, den du jemandem gibst: „Wenn eine Anfrage für / kommt, tu das.“","deep":"<code>[capture](params) { body }</code>. Die Capture-Liste sagt, was sie aus ihrer Umgebung nutzen darf: <code>[this]</code> das aktuelle Objekt, <code>[&amp;]</code> alles per Referenz, <code>[]</code> nichts. Web-Routen, WLAN-Events und Sortieren nehmen hier alle Lambdas."},"variadic":{"short":"Heißt „beliebig viele zusätzliche Argumente“, wie die Werte, die ein printf-Muster braucht.","simple":"„…und so weiter“: Die Funktion nimmt so viele Extras, wie du ihr gibst.","deep":"In <code>void warn(const char *fmt, ...)</code> werden die Extras mit <code>va_list</code> gelesen und an <code>vsnprintf</code> weitergereicht; das Attribut <code>[[gnu::format(printf, 2, 3)]]</code> lässt den Compiler sie gegen das Muster prüfen. In einem Makro fügt <code>__VA_ARGS__</code> sie ein."},"inline":{"short":"Erlaubt, eine Funktion oder Variable in einem Header zu definieren, den viele Dateien einbinden.","simple":"Ein Rezept, das in jedem Kochbuch steht, das es braucht: Die Küche ist sich einig, dass es dasselbe Rezept ist, keine Rivalen.","deep":"Seine eigentliche Aufgabe ist die One-Definition-Rule: Eine <code>inline</code>-Funktion in einer <code>.h</code> darf in vielen <code>.cpp</code>-Dateien vorkommen, ohne dass der Linker streitet. Ob der Aufruf wirklich eingebettet wird, entscheidet der Optimierer. <code>constexpr</code>-Funktionen und in einer Klasse definierte Funktionen sind automatisch inline."},"operator":{"short":"Bringt einem Typ bei, was ein Symbol wie <code>==</code>, <code>[]</code> oder <code>+</code> mit ihm tun soll.","simple":"Wie einer neuen Spielfigur die bestehenden Regeln beibringen: Jetzt funktioniert <code>a == b</code> auch für deine eigene Art von Ding.","deep":"<code>bool operator==(const Uid &amp;o) const</code> ist nur eine Funktion mit besonderem Namen; <code>explicit operator bool()</code> lässt ein Objekt in einem <code>if</code> testen."},"noexcept":{"short":"Ein Versprechen, dass eine Funktion nie eine Exception wirft.","simple":"Ein Schild an der Tür: „Hier drin keine Überraschungen“.","deep":"Wirft sie trotzdem, beendet <code>std::terminate</code> das Programm. Standard-Container nutzen es, um zu entscheiden, ob Verschieben eines Elements sicher ist. Arduino-ESP32 baut mit verfügbaren Exceptions, aber die Labs werfen nie."},"override":{"short":"<code>virtual</code> lässt eine Kindklasse eine Funktion ersetzen; <code>override</code> markiert den Ersatz.","simple":"Ein Formular mit Lücke: Die Bibliothek überlässt dir „wie man ein Pixel zeichnet“, und <code>override</code> sagt „das ist meine Antwort auf diese Lücke“.","deep":"Aufrufe laufen über eine Tabelle von Funktionszeigern (die vtable), also ruft <code>Adafruit_GFX</code>-Code am Ende unser <code>FrameBuffer::drawPixel</code> auf. <code>override</code> lässt den Compiler prüfen, dass ein passendes virtual existiert. NimBLE-Callbacks wie <code>onConnect</code> funktionieren genauso."},"explicit":{"short":"Hindert den Compiler daran, per Konstruktor stillschweigend einen Typ in einen anderen zu verwandeln.","simple":"„Erst fragen“: Eine Zahl wird nicht zu einem <code>Button</code>, nur weil man einen <code>Button</code> aus einer bauen kann.","deep":"Ohne es ist ein Ein-Argument-Konstruktor eine implizite Umwandlung, sodass eine Funktion, die einen <code>BootButton</code> nimmt, mit einer einfachen Zahl aufgerufen werden könnte. Wird auch bei <code>operator bool</code> genutzt."},"constructor":{"short":"Eine besondere Funktion mit dem Namen der Klasse, die ein neues Objekt einrichtet.","simple":"Die Aufbauanleitung, die einmal läuft, wenn ein neues Ding aus der Schachtel kommt.","deep":"Kein Rückgabetyp. Die Liste nach <code>:</code> (<code>: pin_(pin), name_(name)</code>) füllt Mitglieder vor dem Rumpf, in der Reihenfolge ihrer Deklaration. Ein <code>~Name()</code>-Destruktor läuft, wenn das Objekt verschwindet, wie bei <code>FrameBuffer</code>, das seine Pixel freigibt."},"address-reference":{"short":"Drei Aufgaben: nach einem Typ macht es eine Referenz (ein weiterer Name), vor einer Variable nimmt es ihre Adresse, zwischen Zahlen ist es bitweises UND.","simple":"Eine Referenz ist ein Spitzname: <code>uint8_t &amp;r</code> lässt eine Funktion direkt in deine Kiste schreiben. <code>&amp;x</code> ist die Straßenadresse der Kiste. <code>a &amp; b</code> behält nur die Bits, die in beiden an sind.","deep":"<code>T &amp;</code> bindet an ein bestehendes Objekt und kann weder null sein noch umgebogen werden; <code>const T &amp;</code> reicht große Dinge ohne Kopieren weiter. <code>&amp;lock_</code> ergibt einen <code>portMUX_TYPE *</code>. <code>x &amp; 0xFF</code> maskiert das untere Byte."},"pointer":{"short":"Drei Aufgaben: nach einem Typ deklariert es einen Pointer, vor einem Pointer folgt es ihm, zwischen Zahlen multipliziert es.","simple":"Ein Pointer ist ein Zettel mit einer Adresse darauf. <code>*p</code> heißt „geh zu dieser Adresse und nutz, was dort ist“. Zwischen zwei Zahlen heißt es einfach mal.","deep":"Pointer haben auf dem ESP32 4 Byte. <code>uint16_t *buf_</code> hält, wo die Pixel anfangen; <code>buf_[i]</code> ist dasselbe wie <code>*(buf_ + i)</code>. <code>const char *</code> ist ein Pointer auf Text, den du lesen, aber nicht ändern darfst."},"array":{"short":"Eine feste Reihe von Werten desselben Typs, ab 0 nummeriert.","simple":"Ein Eierkarton: eine feste Zahl von Fächern, alle gleich geformt. Die Fachnummern beginnen bei 0, also hat ein Karton mit 6 Fächern die Fächer 0 bis 5.","deep":"<code>char text[32]</code> reserviert genau dort 32 Byte, ohne Heap. Nichts prüft den Index, also trampelt <code>text[32]</code> still über alles, was daneben liegt; <code>sizeof(text)</code> gibt die volle Größe in Byte, darum übergeben Puffer-Aufrufe es."},"const":{"short":"Markiert einen Wert als schreibgeschützt: Einmal gesetzt, darf der Code ihn nicht ändern.","simple":"Ein Etikett mit Filzstift statt Bleistift.","deep":"Anders als <code>constexpr</code> kann der Wert aus laufendem Code kommen (<code>const uint32_t now = millis();</code>). Nach den Klammern einer Memberfunktion verspricht <code>const</code>, dass die Funktion das Objekt nicht ändert. <code>const char *p</code> schützt den Text; <code>char *const p</code> schützt den Pointer."},"static":{"short":"Hält eine Variable für das ganze Programm am Leben oder teilt eine Kopie unter allen Objekten einer Klasse.","simple":"In einer Funktion ist es ein Notizbuch, das zwischen den Besuchen auf dem Tisch liegen bleibt, sodass <code>loop()</code> sich an seinen letzten Wert erinnert.","deep":"Drei Bedeutungen. Eine lokale <code>static</code>-Variable wird einmal angelegt und überlebt zwischen Aufrufen. Ein <code>static</code>-Member gehört zur Klasse, nicht zu jedem Objekt (der Interrupt-Handler <code>onEdge</code> ist static und bekommt das Objekt über <code>arg</code>). Auf Dateiebene macht es einen Namen privat für diese Datei."},"volatile":{"short":"Sagt dem Compiler, dass sich dieser Wert hinter seinem Rücken ändern kann, also muss er ihn jedes Mal neu lesen.","simple":"Ein Briefkasten, der sich füllen kann, während du nicht hinschaust: Du musst hingehen und nachsehen, nicht annehmen, dass er noch leer ist.","deep":"Nötig für Variablen, die ein Interrupt schreibt und normaler Code liest. Es ist <b>kein</b> Lock und nicht atomar: Ein 64-Bit-Wert kann trotzdem zerrissen werden. Für Daten zwischen Tasks nimm lieber <code>std::atomic</code>, einen Mutex oder eine kritische Sektion."},"sizeof":{"short":"Sagt dir, wie viele Bytes ein Typ oder eine Variable belegt.","simple":"Wie die aufgedruckte Füllmenge am Glas lesen, bevor du etwas hineingießt.","deep":"Wird beim Kompilieren ausgerechnet und kostet zur Laufzeit nichts. <code>sizeof(text)</code> eines Arrays ist seine volle Bytegröße, bei einem Pointer aber nur 4. <code>sizeof(arr) / sizeof(arr[0])</code> zählt Elemente."},"new-delete":{"short":"<code>new</code> baut ein Objekt im freien Speicher (dem Heap); <code>delete</code> zerstört es und gibt den Speicher zurück.","simple":"Einen Lagerraum mieten: <code>new</code> mietet einen, <code>delete</code> gibt den Schlüssel zurück. Vergisst du die Rückgabe, ist der Platz bis zum Neustart weg.","deep":"Jedes <code>new</code> braucht genau ein <code>delete</code> (<code>new[]</code> braucht <code>delete[]</code>). Auf dem ESP32 kann einfaches <code>new</code> je nach Größe und Build-Einstellungen im internen RAM oder PSRAM landen; zum Wählen nimm <code>heap_caps_malloc</code>. <code>= delete</code> an einer Funktion verbietet sie, etwa das Kopieren."},"progmem":{"short":"Bittet darum, dass Daten im Flash-Speicher bleiben, statt ins RAM kopiert zu werden.","simple":"Lass das dicke Buch im Bibliotheksregal und lies es dort, statt es auf deinen kleinen Schreibtisch zu kopieren.","deep":"Unverzichtbar auf AVR-Arduinos; auf dem ESP32 ist es als nichts definiert, weil <code>const</code>-Daten ohnehin im speicherabgebildeten Flash bleiben. Es bleibt der Klarheit und Portierbarkeit halber, wie bei der Webseite in <code>kPage</code>."},"iram-attr":{"short":"Legt eine Funktion in den schnellen internen RAM des Chips, damit sie im Moment eines Interrupts laufen kann.","simple":"Den Feuerlöscher an die Tür stellen statt in den Keller: Er muss sofort greifbar sein.","deep":"Normaler Code läuft über einen Cache aus externem Flash, und der Cache wird abgeschaltet, während Flash beschrieben wird (NVS, OTA). Ein Interrupt-Handler im Flash würde den Chip dann abstürzen lassen; <code>IRAM_ATTR</code> hält ihn im IRAM. Alles, was er aufruft, sollte auch im IRAM liegen, also halt Handler winzig."},"c-strings":{"short":"Cs Werkzeuge für Text in <code>char</code>-Arrays: kopieren, vergleichen, messen.","simple":"Mit Buchstabenplättchen von Hand arbeiten: ein Wort auf deine Reihe kopieren, zwei Reihen vergleichen, die Plättchen vor dem Stopp-Plättchen zählen.","deep":"<code>strlcpy(dst, src, sizeof(dst))</code> kopiert sicher und endet immer mit <code>'\\\\0'</code>. <code>strcmp</code> gibt 0 zurück, wenn zwei Texte gleich sind (nicht true!), darum liest sich Code als <code>strcmp(a, b) == 0</code>. <code>strlen</code> zählt Buchstaben, nicht das letzte <code>'\\\\0'</code>."},"memcpy":{"short":"Einen Block roher Bytes kopieren, füllen oder vergleichen.","simple":"Ein ganzes Tablett Eier auf einmal bewegen statt ein Ei nach dem anderen.","deep":"Sie arbeiten mit Bytes und wissen nichts über Typen: Die Länge ist immer in Bytes, also nimm <code>sizeof</code>. <code>memcpy</code> darf sich nicht überlappen (nimm <code>memmove</code>); <code>memcmp</code> gibt 0 bei Gleichheit zurück. Karten-UIDs und BLE-Payloads werden so behandelt."},"struct":{"short":"Bündelt mehrere benannte Werte zu einem neuen Typ.","simple":"Ein Formular mit beschrifteten Feldern: Eine Card hat eine UID, einen Namen und eine Farbe, und sie reisen zusammen.","deep":"Identisch mit <code>class</code>, nur dass Mitglieder standardmäßig <code>public</code> sind. Die Labs nutzen Structs für schlichte Daten (<code>HttpsResult</code>, <code>Frame</code>) und Klassen für Dinge mit Verhalten."},"class":{"short":"Definiert eine neue Art von Objekt: die Daten, die es hält, und die Dinge, die es kann.","simple":"Ein Bauplan für ein Gerät: welche Teile innen sind und welche Knöpfe außen.","deep":"Mitglieder sind standardmäßig <code>private</code>. <code>class FrameBuffer : public Adafruit_GFX</code> erbt alles, was eine GFX-Zeichenfläche kann. <code>enum class</code> verwendet das Wort für etwas anderes: ein Enum mit eigenem Geltungsbereich."},"enum":{"short":"Eine Liste benannter Optionen, wie <code>Click</code>, <code>DoubleClick</code>, <code>LongPress</code>.","simple":"Eine Multiple-Choice-Frage: Die Antwort muss eine der Optionen auf dem Bogen sein.","deep":"<code>enum class Event { ... }</code> hat einen eigenen Geltungsbereich (geschrieben <code>Event::Click</code>) und wird nicht aus Versehen zu einem <code>int</code>. <code>: uint8_t</code> wählt den Speichertyp. Ein einfaches <code>enum</code> lässt seine Namen in den umgebenden Bereich lecken."},"namespace":{"short":"Ein benannter Ordner für Funktionen und Typen, damit sich Namen aus verschiedenen Teilen nie in die Quere kommen.","simple":"Nachnamen für Code: <code>pal::ink</code> und <code>sv::ink</code> können beide existieren, wie zwei Leute namens Sam in verschiedenen Familien.","deep":"Ein unbenannter <code>namespace { }</code> macht alles darin privat für diese <code>.cpp</code>-Datei (interne Bindung), wie Lektion 01 es mit ihren Helfern tut. <code>using namespace x;</code> zieht Namen wieder heraus; vermeide es in Headern."},"std":{"short":"Der Namespace der C++-Standardbibliothek: <code>std::min</code>, <code>std::vector</code>, <code>std::mutex</code>...","simple":"Der Werkzeugkasten, der zu jedem C++-Compiler gehört. <code>std::</code> sagt „nimm dieses Werkzeug aus dem Standardkasten“.","deep":"Arduino-ESP32 bringt eine volle C++-Standardbibliothek mit (GCCs libstdc++), inklusive Containern, Algorithmen, <code>&lt;atomic&gt;</code> und <code>&lt;mutex&gt;</code> auf FreeRTOS. Achte auf den Heap-Verbrauch: Container allokieren."},"access":{"short":"Legen fest, wer die Mitglieder einer Klasse nutzen darf: alle, nur die Klasse selbst oder die Klasse und ihre Kinder.","simple":"Die Knöpfe an der Vorderseite eines Radios sind <code>public</code>; die Platine innen ist <code>private</code>.","deep":"Eine Klasse hält ihre Daten <code>private</code> (hier mit nachgestelltem <code>_</code>, wie in <code>pin_</code>) und bietet <code>public</code>-Funktionen an, sodass sie ihr Inneres ändern kann, ohne Aufrufer zu brechen. In <code>: public Adafruit_GFX</code> legt das Wort fest, wie die Mitglieder des Elternteils geerbt werden."},"this":{"short":"Innerhalb einer Memberfunktion ein Pointer auf das Objekt, an dem die Funktion arbeitet.","simple":"„Ich“: das Objekt, das auf sich selbst zeigt.","deep":"Meist implizit (<code>pin_</code> heißt <code>this->pin_</code>). Wird explizit übergeben, wenn ein Callback im C-Stil seinen Weg zurück finden muss, wie in <code>attachInterruptArg(..., onEdge, this, CHANGE)</code> oder als Parameter eines Tasks, und von Lambdas mit <code>[this]</code> eingefangen."},"using":{"short":"Gibt einem Typ einen kürzeren oder klareren Namen.","simple":"Ein Spitzname: Sag <code>JsonFn</code> statt jedes Mal den ganzen langen Typ.","deep":"<code>using JsonFn = std::function&lt;...&gt;;</code> ist die moderne Form von <code>typedef</code> und liest sich von links nach rechts. <code>using namespace std;</code> und <code>using Base::f;</code> sind andere Verwendungen desselben Worts."},"union":{"short":"Mehrere Mitglieder teilen sich dieselben Bytes, also ist immer nur eines gerade sinnvoll.","simple":"Ein Parkplatz mit mehreren möglichen Autos: Das zuletzt geparkte ist das, das da steht.","deep":"Die Union ist so groß wie ihr größtes Mitglied. Ein anderes Mitglied zu lesen als das zuletzt geschriebene ist in C++ technisch undefiniert (GCC erlaubt es); <code>memcpy</code> oder <code>std::bit_cast</code> sind die saubere Art, Bytes umzudeuten."},"extern":{"short":"Sagt, dass eine Variable existiert, aber woanders im Programm definiert ist.","simple":"„Der Schlüssel liegt im anderen Zimmer“: Du kannst hier darüber reden, und der Linker holt ihn später.","deep":"Eine Deklaration ohne Definition. Der HTTPS-Client nutzt sie, um über seine Linker-Symbolnamen an das Mozilla-Zertifikatspaket zu kommen, das der Build in den Flash linkt."},"constexpr":{"short":"Ein Wert, der beim Kompilieren des Programms feststeht, also kann er sich nie ändern, während das Board läuft.","simple":"Wie eine Zahl, die auf die Kiste gedruckt ist, statt auf einen Haftzettel geschrieben: entschieden, bevor das Board je Strom bekommt.","deep":"<code>constexpr</code>-Variablen berechnet der Compiler, und sie kosten zur Laufzeit kein RAM; eine <code>constexpr</code>-Funktion wie <code>rgb()</code> kann beim Kompilieren laufen, wenn ihre Eingaben Konstanten sind. Die Labs nennen sie <code>kSomething</code>."},"static-cast":{"short":"Wandelt einen Wert absichtlich in einen anderen Typ um, sichtbar für dich.","simple":"Ein Getränk absichtlich und vor aller Augen in ein anderes Glas gießen.","deep":"Vom Compiler geprüft und bei Zahlentypen zur Laufzeit kostenlos. Hier üblich: <code>static_cast&lt;unsigned long&gt;</code>, um zu <code>%lu</code> zu passen, und einen <code>void *</code> in das Objekt zurückzuverwandeln, das er war. Die Kurzform <code>uint8_t(x)</code> tut dasselbe für einfache Typen."},"reinterpret-cast":{"short":"Behandelt dieselben Bytes als völlig anderen Typ, ohne sie zu ändern.","simple":"Eine Seite Zahlen lesen, als wären es Buchstaben: Die Tinte ist dieselbe, nur wie du liest, ändert sich.","deep":"Es findet keine Umwandlung statt; es etikettiert nur einen Pointer um (zum Beispiel <code>uint8_t *</code> zu <code>const char *</code> für einen Byte-Puffer mit Text). Leicht zu missbrauchen: Alignment- und Strict-Aliasing-Regeln gelten weiter."},"const-cast":{"short":"Entfernt <code>const</code> von einem Pointer, damit er an eine Funktion im alten Stil übergeben werden kann.","simple":"Ein mit Filzstift beschriftetes Etikett für eine Funktion ausleihen, die nur Bleistift akzeptiert: Du versprichst, dass sie nicht wirklich schreibt.","deep":"Nur sicher, wenn das Objekt von Haus aus nicht wirklich const war oder wenn der Aufgerufene es nicht ändert (viele C-APIs haben <code>const</code> einfach vergessen). Über ihn in wirklich konstante Daten zu schreiben ist undefiniert."},"template":{"short":"Schreibt eine Funktion oder Klasse einmal für jeden Typ; der Compiler macht für jeden benutzten Typ eine Kopie.","simple":"Ein Ausstechförmchen: eine Form, jeder Teig. <code>T</code> steht für den Teig, bis du ihn wählst.","deep":"<code>template &lt;typename F&gt; void withChip(F &amp;&amp;fn)</code> akzeptiert alles Aufrufbare, auch Lambdas, ohne Laufzeitkosten. Jeder neue Typ heißt eine neue kompilierte Kopie, also lässt starke Nutzung die Firmware wachsen. Spitze Klammern liefern den Typ: <code>std::vector&lt;Card&gt;</code>."},"std-min-max":{"short":"Geben den kleineren oder den größeren von zwei Werten zurück.","simple":"„Was auch immer kleiner ist“ und „was auch immer größer ist“: praktisch, um Zahlen im Bereich zu halten.","deep":"Beide Argumente müssen denselben Typ haben, oder du nennst ihn: <code>std::min&lt;uint32_t&gt;(n, 320)</code>. <code>std::max(0, n - 9)</code> verhindert, dass ein Wert unter null fällt."},"std-clamp":{"short":"Quetscht einen Wert in einen Bereich: Unterhalb des unteren Endes gibt es das untere Ende, oberhalb des oberen Endes das obere Ende.","simple":"Ein Kindergitter auf der Treppe: Du kannst dich bewegen, aber nicht an den Gittern an beiden Enden vorbei.","deep":"C++17, aus <code>&lt;algorithm&gt;</code>. Alle drei Argumente müssen einen Typ teilen, daher <code>0.0f</code> und <code>1.0f</code>. Arduinos <code>constrain()</code> macht dieselbe Arbeit."},"std-algorithms":{"short":"Fertige Schleifen aus der Standardbibliothek: füllen, kopieren, sortieren, das Größte finden...","simple":"Küchengeräte: Du könntest von Hand schneiden, aber das Gerät ist schneller und rutscht nicht ab.","deep":"Aus <code>&lt;algorithm&gt;</code>; sie arbeiten mit jedem Bereich, der als Start- und End-Pointer (oder Iterator) angegeben wird, wobei das Ende eins hinter dem letzten Element liegt. <code>std::fill_n(buf_, n, c)</code> bemalt einen ganzen Bildschirm; <code>std::sort</code> nimmt ein Lambda, das sagt, was „kommt zuerst“ heißt."},"std-move":{"short":"Reicht den Inhalt eines Objekts an ein anderes weiter, statt ihn zu kopieren.","simple":"Mit den Kisten, wie sie sind, umziehen, statt für die neue Wohnung von allem eine Kopie zu kaufen.","deep":"Es ist nur ein Cast auf eine Rvalue-Referenz (<code>T &amp;&amp;</code>); das eigentliche Verschieben erledigt der Move-Konstruktor des empfangenden Typs. Danach ist die Quelle gültig, aber so gut wie leer, also verlass dich nicht auf ihren Wert. Billig für <code>String</code>, <code>std::vector</code> und <code>std::function</code>."},"std-vector":{"short":"Eine Liste, die wachsen und schrumpfen kann und Elemente eines Typs hält.","simple":"Ein Ausziehordner: Leg Blätter dazu, und er macht Platz, und du kannst trotzdem sagen „gib mir Blatt 3“.","deep":"Speichert Elemente in einem zusammenhängenden Heap-Block und verdoppelt ihn, wenn er voll ist, was Speicher verschiebt (und fragmentieren kann). Die Labs füllen Vektoren außerhalb zeitkritischer Pfade, etwa beim Kopieren der Kartenliste für den Bildschirm. <code>v.size()</code>, <code>v.push_back(x)</code>, <code>v[i]</code>."},"std-function":{"short":"Eine Kiste, die jede Funktion oder jedes Lambda mit einer bestimmten Form aufnehmen kann, um es später aufzurufen.","simple":"Ein Fach für einen Haftzettel mit Anweisungen: Jeder Zettel passt, solange er dieselben Eingaben nimmt.","deep":"<code>std::function&lt;void(Card &amp;)&gt;</code> nimmt ein <code>Card &amp;</code> und gibt nichts zurück. Flexibel, aber schwerer als ein Template: Der Aufruf ist indirekt, und große Captures landen auf dem Heap. Gut für Callbacks, die in einer Klasse gespeichert werden."},"std-atomic":{"short":"Eine Variable, die zwei Tasks gleichzeitig lesen und schreiben können, ohne je eine halbe Änderung zu sehen.","simple":"Ein einzelner Lichtschalter, den alle umlegen können: Egal wer ihn anfasst, er ist immer eindeutig an oder aus.","deep":"<code>std::atomic&lt;bool&gt;</code> und <code>std::atomic&lt;uint32_t&gt;</code> sind auf dem ESP32 lock-free. Nutz sie für einen kleinen Wert wie ein Flag oder einen Zähler; für mehrere Werte, die sich gemeinsam ändern müssen, nimm einen Mutex."},"memory-order":{"short":"Sagt, wie streng ein atomares Lesen oder Schreiben mit dem Speicher drumherum abgestimmt sein muss.","simple":"„Release“ ist, als würdest du einen Brief erst einwerfen, wenn er versiegelt ist; „acquire“ ist, ihn zu öffnen, bevor du liest. Zusammen garantieren sie, dass der Leser alles sieht, was der Schreiber vorbereitet hat.","deep":"<code>relaxed</code> macht nur den einen Wert atomar. Ein <code>release</code>-Store, gepaart mit einem <code>acquire</code>-Load, macht alles, was vor dem Store geschrieben wurde, nach dem Load sichtbar, über die zwei Kerne des ESP32 hinweg. Der Standard (<code>seq_cst</code>) ist der strengste."},"std-mutex":{"short":"Ein Schloss, das jeweils nur einen Task in ein Stück Code oder Daten lässt.","simple":"Der einzige Schlüssel zu einem gemeinsamen Bad: Wer ihn hat, geht rein, alle anderen warten an der Tür.","deep":"Auf Arduino-ESP32 baut er auf einem FreeRTOS-Mutex auf, also schläft ein wartender Task, statt zu kreisen. Sperr ihn nie in einem Interrupt. Sperr ihn über <code>std::lock_guard</code>, damit er immer entsperrt wird, auch bei einem frühen <code>return</code>."},"lock-guard":{"short":"Sperrt einen Mutex beim Anlegen und entsperrt ihn am Ende des Blocks automatisch.","simple":"Ein Schlüssel, der sich selbst zurückbringt: Er nimmt den Badschlüssel, wenn du reingehst, und legt ihn von selbst zurück, wenn du gehst, egal wie.","deep":"RAII: Der Konstruktor ruft <code>lock()</code>, der Destruktor ruft <code>unlock()</code>, wenn die Variable den Gültigkeitsbereich verlässt. So kannst du das Entsperren bei einem frühen <code>return</code> nicht vergessen. Halt den Block kurz."},"decltype":{"short":"Fragt den Compiler „welchen Typ hat dieser Ausdruck?“ und nutzt die Antwort als Typ.","simple":"„Gib mir eine Kiste genau wie die da.“","deep":"Wird beim Kompilieren ausgewertet; der Ausdruck läuft nie. Nützlich in Templates und um den Typ eines Lambdas zu benennen."},"static-assert":{"short":"Eine Prüfung, die beim Kompilieren läuft; schlägt sie fehl, stoppt der Build mit deiner Meldung.","simple":"Ein Pförtner in der Fabrik: Ein Teil, das nicht passt, verlässt nie das Gebäude.","deep":"Kostet zur Laufzeit nichts. Typische Nutzung: prüfen, dass ein gepacktes Struct wirklich die Bytegröße hat, die ein Protokoll erwartet, oder dass eine Tabelle einen Eintrag pro Enum-Wert hat."},"mutable":{"short":"Lässt ein Mitglied sich sogar in einer <code>const</code>-Funktion ändern, für Buchführung, die nicht zum Wert des Objekts gehört.","simple":"Ein Notizblock, der an ein versiegeltes Dokument geklammert ist: Das Dokument bleibt gleich, die Notizen können sich ändern.","deep":"Typisch für einen Mutex oder einen Cache in einem Objekt, dessen Lesefunktionen <code>const</code> sind: Sperren ändert den Mutex, aber nicht, was das Objekt bedeutet. Bei einem Lambda lässt <code>mutable</code> es seine eigenen eingefangenen Kopien ändern."},"include":{"short":"Fügt hier eine andere Datei ein, damit diese Datei nutzen kann, was sie deklariert.","simple":"Wie oben auf einem Rezept „siehe beiliegende Rezeptkarte“: Die darin aufgelisteten Zutaten sind jetzt verfügbar.","deep":"<code>&lt;Arduino.h&gt;</code> in spitzen Klammern durchsucht die Bibliotheks- und Systempfade; <code>\\"pins.h\\"</code> in Anführungszeichen sucht zuerst neben dieser Datei (und im <code>include/</code> des Projekts). Es ist reines Text-Einfügen, vor dem Kompilieren."},"pragma-once":{"short":"Sorgt dafür, dass eine Header-Datei nur einmal eingefügt wird, egal wie viele Dateien sie einbinden.","simple":"Ein „das hast du schon gelesen“-Lesezeichen: Beim zweiten Mal wird die Seite übersprungen.","deep":"Von GCC und jedem großen Compiler unterstützt; es ersetzt den älteren Include-Guard <code>#ifndef X / #define X / #endif</code>. Ohne es wäre ein doppelt definiertes Struct ein Compilerfehler."},"define":{"short":"Erzeugt einen Namen, der vor dem Kompilieren des Codes durch Text ersetzt wird.","simple":"Suchen und Ersetzen, vom Computer direkt vor dem Lesen deines Codes: Jedes <code>PIN_RGB</code> wird zu <code>48</code>.","deep":"Makros wissen nichts über Typen oder Geltungsbereiche. <code>pins.h</code> nutzt sie, damit ein Build-Flag wie <code>-DPIN_RGB=38</code> einen Pin überschreiben kann; für gewöhnliche Konstanten nimm lieber <code>constexpr</code>. Ein Makro mit Klammern, wie <code>BLE_NOTE(kind, ...)</code>, fügt seine Argumente ein."},"conditional-compile":{"short":"Behält oder verwirft Codezeilen vor dem Kompilieren, je nachdem, ob ein Name definiert ist.","simple":"„Hat noch niemand einen Pin gewählt, nimm 48.“ Die Zeilen, die nicht zutreffen, werden herausgeschnitten, bevor der Compiler sie je sieht.","deep":"<code>#ifndef PIN_RGB</code> ... <code>#endif</code> lässt Build-Flags aus <code>platformio.ini</code> über die Standardwerte in <code>pins.h</code> siegen. <code>#if</code> testet einen konstanten Ausdruck; jedes <code>#if</code>/<code>#ifdef</code>/<code>#ifndef</code> braucht ein passendes <code>#endif</code>."},"serial-begin":{"short":"Öffnet die serielle Leitung zu deinem Computer mit gewählter Geschwindigkeit, damit das Board Meldungen ausgeben kann.","simple":"Den Hörer abnehmen und vereinbaren, wie schnell ihr beide redet. 115200 ist die Geschwindigkeit, mit der der serielle Monitor zuhört.","deep":"Geschwindigkeit in Baud (Bit pro Sekunde); sie muss zu <code>monitor_speed</code> in <code>platformio.ini</code> passen. In diesen Labs ist <code>Serial</code> UART0, erreicht über den USB-Seriell-Chip am <code>COM</code>-Port, also muss nichts darauf warten, dass USB sich anmeldet."},"serial-printf":{"short":"Gibt eine Zeile im seriellen Monitor aus und setzt Werte über <code>%</code>-Codes ein.","simple":"Ein Serienbrief: <code>\\"%d cores\\"</code> hat eine Lücke, und die Zahl, die du übergibst, füllt sie.","deep":"Formatiert mit <code>vsnprintf</code> und schreibt dann mit 115200 Baud an UART0 (etwa 11,5 KB/s, lange Ausgaben bremsen also eine Schleife). Codes: <code>%d</code> int, <code>%u</code> unsigned, <code>%lu</code> unsigned long, <code>%.1f</code> float, <code>%s</code> C-String (nimm <code>.c_str()</code> für einen <code>String</code>), <code>%02X</code> zweistelliges Hex. Füg <code>\\\\n</code> selbst an."},"serial-print":{"short":"Gibt Text oder eine Zahl im seriellen Monitor aus; <code>println</code> beginnt außerdem eine neue Zeile.","simple":"Etwas laut zu deinem Computer sagen. <code>println</code> ist, als würdest du danach Enter drücken.","deep":"Akzeptiert Text, Zahlen und <code>String</code>; <code>Serial.print(x, HEX)</code> gibt hexadezimal aus. Es schreibt in einen Sendepuffer und wartet nur, wenn der voll ist."},"serial-read":{"short":"<code>available()</code> sagt, wie viele getippte Buchstaben warten; <code>read()</code> nimmt den nächsten.","simple":"Den Briefkasten prüfen: <code>available()</code> sagt dir, wie viele Briefe drin sind, <code>read()</code> nimmt einen heraus.","deep":"Beide kehren sofort zurück; <code>read()</code> gibt -1, wenn nichts wartet. Die Labs sammeln Buchstaben in einem Puffer bis zu einem Zeilenumbruch und führen dann den Befehl aus, sodass Tippen nie den Bildschirm blockiert. <code>flush()</code> wartet, bis alles Ausgegebene gesendet wurde."},"pin-mode":{"short":"Richtet einen GPIO-Pin als Eingang oder Ausgang ein, bevor du ihn benutzt.","simple":"Entscheiden, ob eine Tür zum Hereinkommen (einen Taster lesen) oder zum Hinausgehen (eine LED anschalten) da ist.","deep":"Konfiguriert die GPIO-Matrix für diesen Pin. <code>INPUT_PULLUP</code> schaltet außerdem einen schwachen internen Widerstand nach 3,3 V ein, sodass ein Taster nach GND keine Extrateile braucht. Meide die Strapping-, Flash- und PSRAM-Pins, die oben in <code>pins.h</code> aufgelistet sind."},"pin-modes":{"short":"Die Arten, wie ein Pin eingerichtet werden kann: zuhören, treiben oder zuhören mit eingebautem Widerstand.","simple":"<code>OUTPUT</code> ist ein Hahn, den du auf- und zudrehst. <code>INPUT</code> ist eine Anzeige, die du abliest. <code>INPUT_PULLUP</code> ist eine Anzeige, die auf „high“ ruht, bis etwas sie nach unten zieht.","deep":"Ein schwebender <code>INPUT</code> fängt Rauschen auf; <code>INPUT_PULLUP</code>/<code>INPUT_PULLDOWN</code> aktivieren die schwachen internen Widerstände des ESP32 (einige zehn Kiloohm). Darum lesen gedrückte Taster in diesen Labs <code>LOW</code>."},"digital-write":{"short":"Schaltet einen Ausgangs-Pin an (3,3 V) oder aus (0 V).","simple":"Einen Lichtschalter umlegen: <code>HIGH</code> ist an, <code>LOW</code> ist aus.","deep":"Die Pins des ESP32-S3 haben 3,3 V, nie 5 V. Jeder Pin kann standardmäßig etwa 20 mA liefern oder aufnehmen (einstellbar mit <code>gpio_set_drive_capability</code>), also braucht eine LED immer einen Vorwiderstand."},"digital-read":{"short":"Liest, ob ein Eingangs-Pin high (nahe 3,3 V) oder low (nahe 0 V) ist.","simple":"Einen Klingelknopf fragen: Bist du gerade gedrückt?","deep":"Gibt <code>HIGH</code> (1) oder <code>LOW</code> (0) zurück. Mit <code>INPUT_PULLUP</code> liest ein gedrückter Taster <code>LOW</code>, daher heißt <code>== LOW</code> „gedrückt“. Mechanische Kontakte prellen einige ms lang, was <code>Button</code> herausfiltert."},"high-low":{"short":"Die zwei Pegel eines digitalen Pins: <code>HIGH</code> ist 3,3 V, <code>LOW</code> ist 0 V.","simple":"An und aus, im Spannungsstil.","deep":"Es sind einfach 1 und 0. Auf dem ESP32 liest ein Eingang <code>HIGH</code> oberhalb von etwa drei Vierteln von 3,3 V und <code>LOW</code> unterhalb eines Viertels; dazwischen ist nichts garantiert."},"analog-read":{"short":"Misst die Spannung an einem Pin als Zahl von 0 bis 4095.","simple":"Eine dimmbare Anzeige statt eines An/Aus-Schalters: Wie hoch ist die Spannung auf einer Skala von 0 bis 4095?","deep":"Der ADC des ESP32-S3 hat 12 Bit. Nimm ADC1-Pins (GPIO 1-10): ADC2 teilt sich WLAN. Ein Aufruf ist ein langsamer Sample, darum nutzen die Sound-Labs stattdessen den kontinuierlichen Modus des ADC mit DMA."},"millis":{"short":"Wie viele Millisekunden seit dem Start des Boards vergangen sind.","simple":"Eine Stoppuhr, die beim Einschalten startet und nie stoppt. Vergleich sie mit einem früheren Wert, um zu wissen, wie lange es her ist.","deep":"Gibt ein 32-Bit-<code>unsigned long</code> zurück, abgeleitet vom 64-Bit-<code>esp_timer</code>. Es läuft nach etwa 49,7 Tagen auf 0 über, und <code>millis() - last >= interval</code> bleibt dank vorzeichenloser Mathematik über den Überlauf hinweg korrekt. So tun Schleifen Dinge „alle N ms“ ohne <code>delay()</code>."},"micros":{"short":"Wie viele Mikrosekunden (Millionstelsekunden) seit dem Start des Boards vergangen sind.","simple":"Dieselbe Stoppuhr wie <code>millis()</code>, tausendmal feiner abgelesen.","deep":"32 Bit, also läuft es nach etwa 71,6 Minuten über; in Ordnung, um Kurzes zu messen, nimm <code>esp_timer_get_time()</code> für eine 64-Bit-Uhr, die praktisch nie überläuft."},"delay":{"short":"Pausiert den aktuellen Code für eine Anzahl Millisekunden.","simple":"Ein Nickerchen machen: Nichts anderes in <code>loop()</code> passiert, bis du aufwachst.","deep":"Auf dem ESP32 ruft es <code>vTaskDelay</code> auf, also ist die CPU für andere Tasks (WLAN, BLE, den Sampler) frei, während dieser schläft. Der FreeRTOS-Tick beträgt hier 1 ms. Lange Delays frieren trotzdem Taster und Bildschirm ein, darum nutzen die Labs meist <code>millis()</code>-Prüfungen."},"delay-microseconds":{"short":"Wartet eine winzige Zahl Mikrosekunden, für Hardware, die sehr kurze Pausen braucht.","simple":"Für einen Wimpernschlag die Luft anhalten: zu kurz für ein Nickerchen, also wartest du einfach an Ort und Stelle.","deep":"Ein Busy-Wait: Die CPU kreist, und andere Tasks auf diesem Kern laufen nicht. In Ordnung für ein paar hundert Mikrosekunden (einen Pull-up einschwingen lassen), nie für lange Wartezeiten."},"ledc-attach":{"short":"Macht aus einem Pin einen PWM-Ausgang mit gewählter Frequenz und Auflösung, zum Dimmen von LEDs oder Hintergrundbeleuchtungen.","simple":"Einen sehr schnellen Lichtschalter einrichten, der tausende Male pro Sekunde an- und ausflackert, sodass das Auge „halb hell“ sieht.","deep":"Arduino-ESP32-3.x-API auf der LEDC-Peripherie: <code>ledcAttach(pin, freq, bits)</code> gibt <code>false</code> zurück, wenn kein Kanal oder keine Frequenz passt. 5 kHz bei 8 Bit ergeben Duty-Werte 0-255 ohne sichtbares Flackern."},"ledc-write":{"short":"Legt fest, wie lange der Pin in jedem PWM-Zyklus an bleibt: 0 ist aus, der Höchstwert ist voll an.","simple":"Den Dimmerknopf an diesem schnellen Schalter drehen.","deep":"In Arduino-ESP32 3.x nimmt es den Pin (2.x nahm einen Kanal). Der Duty-Bereich ist 0 bis 2^bits - 1 (0-255 bei 8 Bit) aus <code>ledcAttach</code>; die LEDC-Hardware hält die Wellenform ohne CPU-Arbeit am Laufen."},"rgb-led-write":{"short":"Setzt die Farbe der eingebauten RGB-LED des Boards aus Rot-, Grün- und Blauwerten (je 0-255).","simple":"Farben mischen: ein bisschen Rot, viel Grün, kein Blau. Die LED zeigt die Mischung.","deep":"Die LED auf dem Board ist eine WS2812, die Farbe als präzise getaktete Impulsfolge annimmt; Arduino-ESP32 erzeugt sie mit der RMT-Peripherie. Sie ist sehr hell, darum skalieren die Labs Werte herunter. Hieß in älteren Cores <code>neopixelWrite</code>."},"attach-interrupt":{"short":"Führt eine Funktion in dem Moment aus, in dem sich ein Pin ändert, auch wenn der Rest des Codes beschäftigt ist.","simple":"Eine Türklingel statt aus dem Fenster zu spähen: Das Board wird in dem Moment unterbrochen, in dem jemand drückt.","deep":"<code>CHANGE</code>, <code>RISING</code> oder <code>FALLING</code> wählt, welche Flanken auslösen. <code>attachInterruptArg</code> übergibt auch einen <code>void *</code> (hier <code>this</code>), damit ein statischer Handler sein Objekt findet. Handler müssen kurz sein, mit <code>IRAM_ATTR</code> markiert, und dürfen nur <code>volatile</code> oder atomare Daten anfassen."},"digital-pin-to-interrupt":{"short":"Macht aus einer Pin-Nummer die Interrupt-Nummer, die <code>attachInterrupt</code> erwartet.","simple":"Nachschlagen, welcher Klingeldraht zu welcher Tür gehört.","deep":"Auf dem ESP32 kann jeder GPIO einen Interrupt auslösen, und die Nummer ist der Pin selbst, aber es hinzuschreiben hält den Code portierbar auf Boards, bei denen das anders ist."},"random":{"short":"Wählt eine ganze Zahl zufällig: <code>random(40, 200)</code> gibt 40 bis 199.","simple":"Würfel, deren Seiten du selbst wählst. Die obere Zahl wird nie gewürfelt.","deep":"<code>random(max)</code> gibt 0 bis max-1, <code>random(min, max)</code> min bis max-1. <code>randomSeed(esp_random())</code> startet die Folge mit einer zufälligen Hardware-Zahl, sodass jeder Boot anders aussieht."},"constrain":{"short":"Hält einen Wert zwischen einem niedrigsten und einem höchsten erlaubten Wert.","simple":"Banden auf einer Bowlingbahn: Die Kugel kann dazwischen überall rollen, nie darüber hinaus.","deep":"Arduinos Version von <code>std::clamp</code>: <code>constrain(x, lo, hi)</code>. MIDI-Noten und Velocities müssen bei 0-127 bleiben, darum begrenzt das BLE-MIDI-Lab sie."},"min-max":{"short":"Arduinos Kurzform für den kleineren oder größeren von zwei Werten.","simple":"„Was auch immer kleiner ist“ oder „was auch immer größer ist“. <code>max(2, s / 6)</code> heißt „mindestens 2“.","deep":"Gib beiden Argumenten denselben Typ, um Überraschungen zu vermeiden. Anderswo schreiben die Labs <code>std::min</code>/<code>std::max</code>, die auch einen expliziten Typ akzeptieren: <code>std::min&lt;uint32_t&gt;(n, 320)</code>."},"string-c-str":{"short":"Gibt den Text eines <code>String</code> als einfachen C-String zurück, für Funktionen, die <code>const char *</code> wollen.","simple":"Die Buchstaben aus ihrem dehnbaren Notizbuch nehmen und auf den Tisch legen, für jemanden, der nur Plättchen liest.","deep":"Der Pointer ist nur gültig, solange der <code>String</code> lebt und nicht geändert wird; behalt ihn nie von einem Temporären wie <code>a.toString().c_str()</code> über diese Zeile hinaus. Nötig für <code>%s</code> in printf."},"string-is-empty":{"short":"Einen <code>String</code> fragen, ob er keine Buchstaben hat oder wie viele.","simple":"Ist die Notizbuchseite leer? Wie viele Buchstaben stehen darauf?","deep":"<code>length()</code> zählt Zeichen (Bytes, also zählt ein Emoji als mehrere) und schließt das versteckte <code>'\\\\0'</code> nicht ein. <code>isEmpty()</code> ist dasselbe wie <code>length() == 0</code> und liest sich besser."},"string-substring":{"short":"<code>indexOf</code> findet, wo Text vorkommt; <code>substring</code> schneidet ein Stück heraus.","simple":"Ein Wort in einem Satz mit dem Finger finden und dann den Teil, den du brauchst, mit der Schere ausschneiden.","deep":"Positionen zählen ab 0. <code>substring(from)</code> geht bis zum Ende, <code>substring(from, to)</code> hört kurz vor <code>to</code> auf. <code>indexOf</code> gibt -1, wenn nichts gefunden wird. Jedes <code>substring</code> erzeugt einen neuen <code>String</code> auf dem Heap."},"string-starts-with":{"short":"Prüft, ob ein <code>String</code> mit etwas Text beginnt (oder endet).","simple":"„Beginnt dieser Befehl mit ‚vol ‘?“ Ein schnelles Ja oder Nein.","deep":"Unterscheidet Groß- und Kleinschreibung, darum werden Befehle zuerst klein gemacht (<code>lower.startsWith(...)</code>). So erkennt der serielle Befehlsparser jedes Labs seine Wörter."},"string-trim":{"short":"Text an Ort und Stelle aufräumen: Leerzeichen an den Enden entfernen, die Groß-/Kleinschreibung ändern oder ein Textstück gegen ein anderes tauschen.","simple":"Einen Zettel gerade ziehen, bevor du ihn liest: keine überflüssigen Leerzeichen, alles klein, sodass „Help “ und „help“ dasselbe bedeuten.","deep":"Diese ändern den <code>String</code> selbst und geben nichts zurück, also ruf sie auf einer Kopie auf, die dir gehört: <code>String lower = line; lower.toLowerCase();</code>. <code>trim</code> entfernt auch das <code>\\\\r</code>, das manche Terminals senden."},"string-to-int":{"short":"Macht aus Text wie <code>\\"42\\"</code> die Zahl 42.","simple":"Die Ziffern auf einem Zettel lesen und in einen Taschenrechner tippen.","deep":"Gibt ein <code>long</code> (oder <code>float</code>) zurück. Text, der nicht mit einer Zahl beginnt, ergibt 0, also sehen eine getippte <code>0</code> und Unsinn gleich aus; prüf den Text, wenn das wichtig ist."},"spi-begin":{"short":"Startet den SPI-Bus an den Pins deiner Wahl, damit das Board schnell mit dem Bildschirm oder dem RFID-Leser sprechen kann.","simple":"Eine private Telefonleitung legen, mit getrennten Drähten zum Sprechen, Zuhören und für den Takt, nach dem sich beide Seiten richten.","deep":"<code>SPI.begin(sck, miso, mosi, ss)</code>; -1 überspringt einen Pin (das Display hat kein MISO). <code>SPI</code> ist das SPI2 (FSPI) des S3; der RFID-Track baut ein zweites <code>SPIClass</code> auf SPI3, damit die beiden nie Drähte oder Takt teilen."},"log-macros":{"short":"Geben eine getaggte Log-Zeile aus: <code>i</code> Info, <code>w</code> Warnung, <code>e</code> Fehler, <code>d</code> Debug.","simple":"Notizen in einem Schiffslogbuch, jede mit einem Stempel, der sagt, wie ernst sie ist.","deep":"Arduino-ESP32-Makros mit Mustern im printf-Stil. Jeder Zeile werden Stufe, Datei, Zeile und Funktion vorangestellt, und Zeilen oberhalb von <code>CORE_DEBUG_LEVEL</code> (3 = Info in <code>platformio.ini</code>) werden beim Kompilieren entfernt, also kostet <code>log_d</code> hier nichts. Die Ausgabe geht an denselben seriellen Port wie <code>Serial</code>."},"esp-info":{"short":"Den Chip über sich selbst fragen: Modell, Kerne, Takt, Flash- und PSRAM-Größe, MAC-Adresse.","simple":"Das Board, das seine eigene Ausweiskarte laut vorliest.","deep":"Lektion 01 erwartet <i>ESP32-S3</i>, 2 Kerne mit 240 MHz, 16 MB Flash (das N16) und etwa 8 MB PSRAM (das R8). <code>getEfuseMac()</code> gibt die MAC ab Werk aus dem eFuse als <code>uint64_t</code> zurück, niedrigstes Byte zuerst."},"free-heap":{"short":"Wie viel Speicher für neue Allokationen noch frei ist.","simple":"Nachsehen, wie viel Platz im Schrank noch ist, bevor du mehr kaufst.","deep":"<code>ESP.getFreeHeap()</code> zählt internes RAM; <code>heap_caps_get_free_size(MALLOC_CAP_SPIRAM)</code> zählt PSRAM. Frei ist nicht gleich nutzbar: <code>heap_caps_get_largest_free_block</code> sagt dir das größte einzelne Stück, und das braucht ein Framebuffer."},"esp-restart":{"short":"Startet den Chip von Grund auf neu, als hättest du die Reset-Taste gedrückt.","simple":"Aus- und wieder einschalten, aus dem Programm heraus.","deep":"Ein Software-Reset: Das RAM wird gelöscht, NVS (Preferences) überlebt, und <code>esp_reset_reason()</code> meldet beim nächsten Mal <code>ESP_RST_SW</code>. Wird nach dem Ändern einer gespeicherten Einstellung genutzt, die nur beim Start wirkt."},"esp-reset-reason":{"short":"Sagt dir, warum das Board zuletzt gestartet ist: Einschalten, Reset-Taste, Absturz, Brown-out...","simple":"Aufwachen und fragen „Hab ich nur geschlafen, oder bin ich umgefallen?“","deep":"Gibt ein <code>esp_reset_reason_t</code> zurück, etwa <code>ESP_RST_POWERON</code>, <code>ESP_RST_SW</code>, <code>ESP_RST_PANIC</code>, <code>ESP_RST_TASK_WDT</code> oder <code>ESP_RST_BROWNOUT</code> (Versorgungsspannung eingebrochen). Beim Boot ausgegeben, macht es Abstürze sichtbar."},"esp-timer-get-time":{"short":"Mikrosekunden seit dem Boot, von einer 64-Bit-Uhr, die nie ausgeht.","simple":"Eine sehr genaue Stoppuhr: gut, um zu messen, wie lange das Zeichnen eines Bildschirmbilds dauerte.","deep":"Gibt <code>int64_t</code> vom hochauflösenden Timer von ESP-IDF zurück; aus einem Interrupt heraus sicher aufrufbar. <code>millis()</code> und <code>micros()</code> bauen darauf auf. Der Taster-Handler behält nur die unteren 32 Bit, sodass ein Lesen ein einzelner Schritt ist."},"esp-timer":{"short":"Richtet einen Callback ein, den ESP-IDF nach einer Verzögerung oder in gleichmäßigem Takt ausführt, mit Mikrosekunden-Timing.","simple":"Ein Küchenwecker, der alle 125 ms klingelt, egal was der Rest des Codes tut.","deep":"Callbacks laufen im <code>esp_timer</code>-Task mit hoher Priorität, nicht in <code>loop()</code>, also halt sie kurz und teil Daten sicher. Perioden sind in Mikrosekunden."},"esp-random":{"short":"Eine zufällige 32-Bit-Zahl vom Hardware-Zufallsgenerator des Chips.","simple":"Würfel, die von Physik im Chip gewürfelt werden statt von einer Formel.","deep":"Wirklich zufällig, solange WLAN oder Bluetooth laufen (Funkrauschen speist es); davor betrachte es nur als Pseudozufall. <code>esp_fill_random(buf, n)</code> füllt einen Puffer, wie es das Vault-Lab für seinen geheimen Schlüssel tut."},"heap-caps-malloc":{"short":"Fordert einen Speicherblock aus einer gewählten Art RAM an: schnell intern oder groß extern (PSRAM).","simple":"Wählen zwischen der kleinen Schublade am Schreibtisch (schnell erreichbar) und dem großen Lagerraum am Ende des Flurs (geräumig, aber langsamer).","deep":"Der S3 hat etwa 512 KB internes SRAM und hier 8 MB Octal-PSRAM. <code>MALLOC_CAP_INTERNAL</code> oder <code>MALLOC_CAP_SPIRAM</code> wählt den Pool; das Ergebnis ist <code>nullptr</code>, wenn kein Block groß genug ist. Gib ihn mit <code>heap_caps_free</code> frei."},"gpio-drive":{"short":"Wählt, wie stark ein Ausgangs-Pin Strom treibt, von schwach bis stark.","simple":"Einstellen, wie hart ein Hahn Wasser drücken kann: ein sanftes Rinnsal oder voller Druck.","deep":"Ein ESP-IDF-Aufruf (er braucht ein <code>gpio_num_t</code>, daher der Cast). Die Stufen 0-3 sind grob 5, 10, 20 (Standard) und 40 mA. Ein schwächerer Treiber macht Flanken sanfter und LEDs dunkler."},"esp-err":{"short":"ESP-IDF-Funktionen antworten mit einem Ergebniscode; <code>ESP_OK</code> (0) heißt, es hat geklappt.","simple":"Ein Beleg: „OK“ oder ein Grund, warum nicht.","deep":"Jeder andere Wert ist ein Fehler wie <code>ESP_ERR_NO_MEM</code> oder <code>ESP_ERR_TIMEOUT</code>; <code>esp_err_to_name()</code> macht daraus Text fürs Log. Die Labs prüfen <code>!= ESP_OK</code> und steigen aus, statt abzustürzen."},"preferences":{"short":"Speichert kleine Einstellungen im Flash des Chips, damit sie Ausschalten und Neuflashen überleben.","simple":"Ein Notizbuch, das ins Board geklebt ist: Schreib „WLAN-Name = home“, und es steht morgen noch da.","deep":"Arduinos Hülle um ESP-IDF NVS, einen Key-Value-Speicher in einer eigenen Flash-Partition. <code>begin(\\"ns\\", readOnly)</code> öffnet einen Namespace; Namespaces und Keys haben höchstens 15 Zeichen. Standardmäßig nicht verschlüsselt; ruf <code>end()</code> auf, wenn du fertig bist."},"preferences-put-get":{"short":"Schreibt einen Wert unter einen Schlüssel oder liest ihn mit einem Fallback zurück, falls er nie gespeichert wurde.","simple":"Beschriftete Gläser im Regal: Leg etwas in das Glas namens „vol“ und nimm es später wieder heraus.","deep":"Der Typ steckt im Namen (<code>UChar</code> = <code>uint8_t</code>, <code>UInt</code> = <code>uint32_t</code>). <code>getX(key, fallback)</code> gibt den Fallback zurück, wenn der Schlüssel fehlt. Schreiben kostet Flash-Verschleiß, darum speichern die Labs nur bei Änderung."},"x-task-create":{"short":"Startet einen neuen Task: eine Funktion, die neben <code>loop()</code> läuft, auf einem Kern deiner Wahl.","simple":"Einen zweiten Koch einstellen. Er hat sein eigenes Rezept und arbeitet gleichzeitig mit dir, an seinem eigenen Herd.","deep":"Argumente: Funktion, Name, Stack-Größe, ein <code>void *</code>-Parameter (oft <code>this</code>), Priorität, ein optionales Handle, Kern. In ESP-IDF ist die Stack-Größe in <b>Bytes</b>. <code>loop()</code> läuft auf Kern 1; die Labs legen ihre Leser und Sampler auf Kern 0. Gibt bei Erfolg <code>pdPASS</code> zurück."},"v-task-delay":{"short":"Schickt diesen Task für eine Anzahl Ticks schlafen, damit andere Tasks die CPU bekommen.","simple":"Der zweite Koch, der kurz vom Herd zurücktritt, damit jemand anderes ihn nutzen kann.","deep":"Ticks sind bei Arduino-ESP32 1 ms, aber schreib <code>pdMS_TO_TICKS(ms)</code>, damit die Bedeutung klar ist. Die Endlosschleife eines Tasks muss irgendwo blockieren oder warten, sonst verhungern Tasks mit niedrigerer Priorität und der Watchdog meckert."},"pd-ms-to-ticks":{"short":"Wandelt Millisekunden in FreeRTOS-Ticks um, die Einheit, die jedes Warten in FreeRTOS nutzt.","simple":"Minuten in die eigenen Einheiten der Küchenuhr übersetzen.","deep":"Ein Makro: <code>ms * configTICK_RATE_HZ / 1000</code>. Mit dem 1000-Hz-Tick hier ist es eins zu eins, aber der Code bleibt richtig, wenn sich die Tick-Rate ändert. Wartezeiten kürzer als ein Tick werden auf 0 abgerundet."},"port-max-delay":{"short":"„Ewig warten“: Übergib es als Timeout, um zu blockieren, bis etwas ankommt.","simple":"Am Briefkasten sitzen, bis die Post kommt, egal wie lange es dauert.","deep":"Der größte Tick-Wert, den FreeRTOS als kein Timeout behandelt. Gut für einen Worker-Task, der sonst nichts zu tun hat; nutz es nie in <code>loop()</code> oder einem Interrupt."},"pd-true":{"short":"Die eigenen Ja/Nein-Antworten von FreeRTOS: <code>pdTRUE</code>/<code>pdPASS</code> heißen, es hat geklappt.","simple":"Der Beleg, den FreeRTOS nach einer Queue- oder Task-Anfrage zurückgibt.","deep":"Einfache Ganzzahlen (<code>BaseType_t</code>), 1 für wahr/bestanden und 0 für falsch/gescheitert. Vergleich explizit damit: <code>xQueueSend(...) == pdTRUE</code>."},"x-queue-create":{"short":"Erzeugt eine Queue: einen sicheren Briefkasten, um Elemente von einem Task zu einem anderen zu reichen.","simple":"Ein Briefkasten mit fester Zahl von Fächern: Ein Task wirft Briefe ein, ein anderer nimmt sie heraus, und sie stoßen nie zusammen.","deep":"<code>xQueueCreate(length, itemSize)</code> gibt ein <code>QueueHandle_t</code> zurück, oder null, wenn der Speicher ausgeht. Elemente werden hinein- und heraus<b>kopiert</b>, also schick kleine Structs, keine Pointer auf Dinge, die verschwinden könnten."},"x-queue-send":{"short":"Legt eine Kopie eines Elements in eine Queue und wartet bis zu einem Timeout, wenn sie voll ist.","simple":"Einen Brief in den Briefkasten werfen. Ist der Kasten voll, kannst du kurz warten oder weggehen.","deep":"Ein Timeout von 0 blockiert nie und gibt <code>errQUEUE_FULL</code> zurück, wenn kein Platz ist: richtig für <code>loop()</code> und Web-Handler, die nicht stocken dürfen. Aus einem Interrupt nimm die <code>FromISR</code>-Version."},"x-queue-receive":{"short":"Nimmt das nächste Element aus einer Queue und wartet bis zu einem Timeout, wenn sie leer ist.","simple":"Den Briefkasten öffnen: den ältesten Brief nehmen oder ein bisschen auf einen warten.","deep":"Elemente kommen der Reihe nach heraus, in deine Variable kopiert. Ein Worker-Task blockiert hier typischerweise mit einem Timeout (oder <code>portMAX_DELAY</code>) und braucht keine CPU, bis Arbeit ankommt."},"semaphore":{"short":"Ein Signal, auf das ein Task wartet und das ein anderer (oder ein Interrupt) gibt.","simple":"Ein Staffelstab beim Staffellauf: Der Läufer wartet, bis der Stab übergeben wird, dann rennt er los.","deep":"Der MFRC522-Treiber schläft in <code>xSemaphoreTake(done_, timeout)</code>, bis der IRQ-Interrupt des Lesers <code>xSemaphoreGiveFromISR</code> aufruft, also ist kein SPI-Polling nötig. Ein Mutex-Semaphor ergänzt Prioritätsvererbung fürs Sperren."},"task-handle":{"short":"Ein Handle benennt einen laufenden Task; <code>vTaskDelete</code> beendet einen.","simple":"Das Namensschild des zweiten Kochs und der Zettel, der ihn nach Hause schickt.","deep":"<code>vTaskDelete(nullptr)</code> beendet den aufrufenden Task; eine Task-Funktion darf nie einfach zurückkehren. <code>uxTaskGetStackHighWaterMark</code> zeigt, wie nah ein Task an einen Stack-Überlauf kam."},"critical-section":{"short":"Sperrt ein paar Zeilen, sodass währenddessen kein anderer Task, Kern oder Interrupt dieselben Daten anfassen kann.","simple":"Die Tür eine Sekunde mit dem Fuß zuhalten, während du zwei Dinge im Regal tauschst.","deep":"Nimmt einen <code>portMUX_TYPE</code>-Spinlock und schaltet Interrupts auf diesem Kern ab, also funktioniert es über beide ESP32-Kerne und mit Interrupts. Halt den Abschnitt bei ein paar Kopien: kein Ausgeben, kein Warten, keine Allokation."},"adafruit-st7789":{"short":"Der Treiber für den 1,9-Zoll-Farbbildschirm mit 320×170, ab Lektion 03 genutzt.","simple":"Der Dolmetscher zwischen Board und Bildschirm: Du sagst „zeichne das“, er spricht die Sprache des Bildschirms über SPI.","deep":"Adafruits ST7789-Treiber. <code>init(170, 320)</code> setzt die Panelgröße, <code>setRotation(1)</code> dreht es ins Querformat, <code>setSPISpeed</code> schiebt den Takt auf 40 MHz hoch. Pixel sind RGB565."},"adafruit-gfx":{"short":"Die Zeichenbibliothek hinter jedem Bildschirmaufruf: Linien, Kreise, Rechtecke, Text.","simple":"Ein Kasten mit Schablonen und Stiften. Jeder Bildschirm, der einen Pixel färben kann, bekommt alle anderen Formen gratis.","deep":"Eine abstrakte Basisklasse: Eine Unterklasse muss nur <code>drawPixel</code> umsetzen, und alles andere baut darauf auf (unser <code>FrameBuffer</code> überschreibt zur Beschleunigung auch die Linien- und Füllaufrufe). Koordinaten sind <code>int16_t</code>, von der linken oberen Ecke aus."},"gfx-canvas16":{"short":"Ein Bild im Speicher außerhalb des Bildschirms, auf das du zeichnest und das du dann in einem Rutsch an den Bildschirm schickst.","simple":"Erst auf Papier skizzieren und dann die fertige Seite gegen das Fenster halten, damit niemand eine halbe Zeichnung sieht.","deep":"Die 16-Bit-Leinwand von Adafruit GFX: ein <code>uint16_t</code> pro Pixel, 320×170×2 = etwa 106 KB. Sie allokiert mit einfachem <code>malloc</code>, was hier im PSRAM landet; unser <code>FrameBuffer</code> bevorzugt stattdessen internes RAM."},"frame-buffer":{"short":"Das Offscreen-Bild dieses Projekts: Zeichne mit den normalen GFX-Aufrufen hinein und schieb es dann auf den Bildschirm.","simple":"Unser eigener Skizzenblock, in der schnellsten Schublade aufbewahrt, die Platz hat.","deep":"Definiert in <code>kit/lib/bench/src/frame_buffer.h</code>. <code>begin()</code> versucht zuerst schnelles internes RAM und weicht auf PSRAM aus, und <code>internal()</code> sagt, was es bekommen hat. Es überschreibt <code>drawPixel</code>, <code>fillScreen</code> und die Linien- und Rechteckaufrufe mit direkten Schreibzugriffen in <code>pixels()</code>."},"display":{"short":"Der Bildschirm-Helfer dieses Projekts: der ST7789, seine Hintergrundbeleuchtung und der Framebuffer, in jedem Lab gleich eingerichtet.","simple":"Der Bildschirm und sein Skizzenblock zusammen verpackt: Zeichne auf <code>fb()</code>, dann zeigt <code>push()</code> es an.","deep":"Definiert in <code>kit/lib/bench/src/display.h</code>. <code>begin()</code> startet PWM an der Hintergrundbeleuchtung, SPI mit 40 MHz und das Panel im Querformat; <code>push()</code> schickt das ganze Bild mit einem <code>drawRGBBitmap</code>."},"button":{"short":"Der Taster-Helfer dieses Projekts: macht aus rohen Tastendrücken saubere Klicks, Doppelklicks und lange Drücke.","simple":"Ein Türsteher für den Taster: Er ignoriert das Zittern der Metallkontakte und sagt dir, was die Person wirklich gemeint hat.","deep":"Definiert in <code>kit/lib/bench/src/button.h</code>. Ein <code>IRAM_ATTR</code>-Interrupt zählt jede Flanke; <code>poll()</code> akzeptiert einen neuen Pegel nach 25 ms Ruhe und meldet <code>Event::Click</code>, <code>DoubleClick</code> (innerhalb von 280 ms) oder <code>LongPress</code> (600 ms)."},"lab-shell":{"short":"Die gemeinsame Shell, auf der die Labs jedes Tracks aufbauen: Bildschirm, Taster, LED, serielle Befehle und Hooks.","simple":"Eine fertig gebaute Werkbank. Jedes Lab bringt nur seine eigenen Werkzeuge (Ansichten und Befehle) mit und steckt sie ein.","deep":"Ein Lab ist ein <code>...Spec</code>: seine Ansichten (Zeichenfunktionen plus eine Doppelklick-Aktion), seine seriellen Befehle und Hooks wie <code>setup</code>, <code>tick</code> und <code>gesture</code>. <code>lab.warn</code> und <code>lab.note</code> geben Meldungen im printf-Stil ins Log und auf den Bildschirm aus. Jede <code>src/&lt;lab&gt;/main.cpp</code> besteht größtenteils aus dieser Liste, also zeigt <code>help</code> genau, was die Lektion lehrt."},"mfrc522":{"short":"Der eigene Treiber dieses Projekts für den RC522-Kartenleser, Register für Register ohne Bibliothek geschrieben.","simple":"Direkt mit dem Leser-Chip sprechen, ein Byte nach dem anderen, damit du jedes Wort des Gesprächs siehst.","deep":"Definiert in <code>kit/lib/rfid-kit/src/mfrc522.h</code>: SPI-Framing, Register, FIFO, der Timer des Chips und entweder Polling oder Schlafen auf seiner IRQ-Leitung. <code>iso14443a.h</code> und <code>mifare_classic.h</code> bauen das Kartenprotokoll darauf auf."},"rgb565":{"short":"Macht aus Rot, Grün und Blau (oder einem Farbton auf dem Farbrad) eine 16-Bit-Bildschirmfarbe.","simple":"Farben mischen und die Mischung dann als einen einzigen Code aufschreiben, den der Bildschirm versteht.","deep":"RGB565 behält 5 Bit Rot, 6 Grün und 5 Blau: <code>((r &amp; 0xF8) &lt;&lt; 8) | ((g &amp; 0xFC) &lt;&lt; 3) | (b &gt;&gt; 3)</code>. Unser <code>rgb()</code> ist <code>constexpr</code>, also kosten Palettenfarben zur Laufzeit nichts."},"gfx-fill-screen":{"short":"Bemalt den ganzen Bildschirm (oder die Leinwand) in einer Farbe.","simple":"Ein frischer Anstrich über alles, meist der erste Schritt beim Zeichnen eines neuen Bilds.","deep":"Bei unserem <code>FrameBuffer</code> ist es ein einzelnes <code>std::fill_n</code> über 54 400 Pixel; auf dem Panel selbst streamt es so viele Pixel über SPI."},"gfx-draw-pixel":{"short":"Färbt einen einzelnen Punkt bei x, y.","simple":"Ein Punkt von einem Filzstift.","deep":"Die eine Funktion, die jede Adafruit-GFX-Fläche liefern muss; alle anderen Formen lassen sich daraus bauen. Unsere prüft die Grenzen und schreibt <code>buf_[y * _width + x]</code>."},"gfx-rect":{"short":"Zeichnet ein Rechteck aus linker oberer Ecke, Breite und Höhe: gefüllt, als Umriss oder mit runden Ecken.","simple":"Eine Kastenform aufs Bild stempeln.","deep":"Argumente: <code>(x, y, w, h, colour)</code>, plus ein Eckenradius für die runden Versionen. <code>fill</code> füllt das Innere, <code>draw</code> nur den Umriss. Balken, Panels und Tasten auf jedem Lab-Bildschirm bestehen daraus."},"gfx-circle":{"short":"Zeichnen runde Formen und Dreiecke: Kreise aus Mittelpunkt und Radius, Dreiecke aus drei Ecken.","simple":"Ein Zirkel und ein Geodreieck für den Bildschirm.","deep":"<code>fillCircle(cx, cy, r, colour)</code> nimmt den Mittelpunkt, nicht eine Ecke. Dreiecke nehmen <code>(x0, y0, x1, y1, x2, y2, colour)</code>. Alles aus schnellen waagerechten Linien auf unserem Framebuffer gebaut."},"gfx-line":{"short":"Zeichnen eine gerade Linie zwischen zwei Punkten oder eine schnelle waagerechte oder senkrechte.","simple":"Ein Lineal und ein Bleistift. Die „schnellen“ gehen nur gerade quer oder gerade nach unten und sind viel schneller.","deep":"<code>drawLine(x0, y0, x1, y1, c)</code> nutzt den Bresenham-Algorithmus, ein Pixel nach dem anderen. <code>drawFastHLine(x, y, w, c)</code> füllt eine Pixelreihe mit einem <code>std::fill_n</code> auf unserem Framebuffer, also nutzen Trennlinien und Balken sie."},"gfx-cursor":{"short":"<code>setCursor</code> legt fest, wo Text beginnt; <code>fb.print</code> schreibt dann dort Text auf den Bildschirm.","simple":"Den Stift an einer Stelle aufsetzen, bevor du schreibst.","deep":"Bei der eingebauten Schrift ist der Punkt die linke obere Ecke des Texts; bei einer eigenen <code>GFXfont</code> ist es das linke Ende der Grundlinie, also muss y tiefer sein. <code>print</code> und <code>printf</code> (dieselben <code>%</code>-Codes wie <code>Serial.printf</code>) schieben den Cursor beim Schreiben weiter."},"gfx-text-style":{"short":"Wähl Farbe, Größe und Schrift des Texts, den du als Nächstes ausgibst.","simple":"Aussuchen, welchen Stift und welche Buchstabenschablone du nimmst.","deep":"<code>setTextColor(fg)</code> zeichnet transparenten Text; <code>setTextColor(fg, bg)</code> malt auch den Hintergrund (nur eingebaute Schrift). <code>setFont(&amp;FreeSans9pt7b)</code> wählt eine glatte Schrift, die mit Adafruit GFX kommt (9 pt, normal); <code>setFont(nullptr)</code> kehrt zur eingebauten 6×8-Schrift zurück; <code>setTextSize(2)</code> verdoppelt sie."},"gfx-text-bounds":{"short":"Misst, wie breit und hoch ein Text wäre, ohne ihn zu zeichnen.","simple":"Ein Schild ausmessen, bevor du es aufhängst, damit du es an der Wand zentrieren kannst.","deep":"<code>getTextBounds(text, x, y, &amp;x1, &amp;y1, &amp;w, &amp;h)</code> füllt das Rechteck aus, das der Text mit der aktuellen Schrift und Größe belegen würde; wird genutzt, um Beschriftungen zu zentrieren und rechtsbündig zu setzen."},"gfx-rgb-bitmap":{"short":"Kopiert einen ganzen Pixelblock in einem Rutsch auf den Bildschirm.","simple":"Ein fertiges Foto in den Rahmen schieben, statt es Punkt für Punkt zu malen.","deep":"<code>drawRGBBitmap(x, y, pixels, w, h)</code> streamt RGB565-Daten über SPI; ein volles 320×170-Bild sind etwa 106 KB, grob 22 ms bei 40 MHz. Das ist die Obergrenze der Bildrate, darum zeichnen die Labs zuerst offscreen."},"gfx-rotation":{"short":"Dreht das Bild des Bildschirms in 90°-Schritten, damit es richtig herum steht.","simple":"Einen Bilderrahmen vom Hoch- ins Querformat drehen.","deep":"0-3 sind 0°, 90°, 180°, 270°. Rotation 1 macht aus dem 170×320-Panel einen 320×170-Querformat-Bildschirm; Breite und Höhe tauschen entsprechend."},"wifi-begin":{"short":"Beginnt, sich mit einem WLAN-Netz zu verbinden, mit Namen und Passwort.","simple":"Mit dem Passwort an der Tür des Routers klopfen; die Antwort kommt ein paar Sekunden später.","deep":"Kehrt sofort zurück; das Verbinden läuft im Hintergrund im WLAN-Task. Unsere <code>Connection</code>-Klasse hört auf die Events (verbunden, IP erhalten, getrennt), statt in einer Schleife zu warten. <code>nullptr</code> als Passwort verbindet mit einem offenen Netz."},"wifi-mode":{"short":"Wählt, ob das Board einem Netz beitritt (Station), ein eigenes aufmacht (Access Point) oder beides.","simple":"Gast auf der Party von jemand anderem sein, eine eigene geben oder beides gleichzeitig.","deep":"<code>WIFI_AP_STA</code> betreibt beides auf einem Funkmodul, also teilen sie sich einen Kanal; das Einrichtungsportal nutzt es, um eine Seite zu zeigen, während es dein Netz versucht. <code>softAP</code> startet das eigene Netz des Boards, standardmäßig unter <code>192.168.4.1</code> erreichbar."},"wifi-info":{"short":"Fragt die WLAN-Verbindung nach Details: IP-Adresse des Boards, Signalstärke, Kanal, MAC.","simple":"Die Hausnummer des Boards im Netz ablesen und wie viele Balken Signal es hat.","deep":"<code>localIP()</code> ist eine <code>IPAddress</code> (<code>toString()</code> für Text). <code>RSSI()</code> ist in dBm: etwa -50 ist ausgezeichnet, unter -80 ist schwach. Alles ist 0 oder leer, bis die Verbindung steht."},"wifi-scan":{"short":"Lauscht nach WLAN-Netzen in der Nähe und listet ihre Namen, ihr Signal und ihre Sicherheit auf.","simple":"Am Radio drehen, um zu hören, welche Sender in der Nähe sind.","deep":"Mit <code>async = true</code> kehrt es sofort zurück (-1, läuft noch); frag <code>scanComplete()</code> nach der Anzahl ab, lies jeden Eintrag, dann gibt <code>scanDelete()</code> die Liste frei. Ein Scan dauert über alle Kanäle ein paar Sekunden."},"wifi-events":{"short":"Meldet eine Funktion an, die der WLAN-Treiber aufruft, wenn etwas passiert: verbunden, IP erhalten, getrennt.","simple":"Die Empfangsdame bitten, dich anzuklingeln, wenn dein Besuch ankommt, statt in der Lobby zu warten.","deep":"Der Callback läuft im WLAN-Event-Task, nicht in <code>loop()</code>, also sollte er nur Flags setzen; <code>loop()</code> macht die eigentliche Arbeit. <code>info</code> trägt Details wie den Trennungsgrund."},"mdns":{"short":"Gibt dem Board in deinem Netz einen freundlichen Namen wie <code>bench.local</code>.","simple":"Ein Namensschild, damit andere Geräte das Board finden, ohne seine Nummer zu kennen.","deep":"Multicast DNS beantwortet Namensanfragen nur im lokalen Netz; macOS und iOS unterstützen es von Haus aus. <code>addService(\\"http\\", \\"tcp\\", 80)</code> bewirbt auch den Webserver."},"ntp-time":{"short":"Stellt die Uhr nach Internet-Zeitservern und liest dann Datum und Uhrzeit vor Ort.","simple":"Das Board hat keine batteriegepufferte Uhr, also fragt es das Internet „wie spät ist es?“, sobald es online ist.","deep":"<code>configTzTime(tz, server1, server2)</code> setzt die POSIX-Zeitzone und startet SNTP. <code>getLocalTime(&amp;tm, timeoutMs)</code> füllt ein <code>struct tm</code> und gibt <code>false</code> zurück, bis die erste Synchronisation passiert ist."},"http-client":{"short":"Stellt Webanfragen vom Board aus, wie ein winziger Browser: eine URL anfragen, die Antwort zurückbekommen.","simple":"Einen Brief an eine Website schicken und auf ihre Antwort warten.","deep":"Der HTTP-Client von Arduino-ESP32 über eine TCP- oder TLS-Verbindung. Unser <code>https::get</code> prüft das Zertifikat des Servers gegen die mitgelieferten Mozilla-Roots. Er blockiert 0,3 s bis mehrere Sekunden, also ruf ihn aus einem Worker-Task auf, nie aus <code>loop()</code>."},"json-document":{"short":"Der Container von ArduinoJson für JSON-Daten: Füll ihn wie ein Wörterbuch oder lies einen, den du empfangen hast.","simple":"Eine Ablage mit beschrifteten Mappen: <code>doc[\\"heap\\"] = 1234</code> legt eine Zahl in die Mappe namens heap.","deep":"ArduinoJson 7: Ein <code>JsonDocument</code> wächst bei Bedarf auf dem Heap. <code>doc[\\"k\\"].to&lt;JsonArray&gt;()</code> macht verschachtelte Arrays; <code>doc[\\"k\\"] | fallback</code> liest mit einem Standardwert, falls der Schlüssel fehlt oder den falschen Typ hat."},"serialize-json":{"short":"Macht aus einem <code>JsonDocument</code> JSON-Text, bereit zum Senden.","simple":"Den Inhalt der Ablage zu einem ordentlichen Brief abtippen.","deep":"<code>serializeJson(doc, out)</code> schreibt in einen <code>String</code>, einen <code>char</code>-Puffer oder einen Stream wie <code>Serial</code> und gibt die Zahl der geschriebenen Bytes zurück."},"deserialize-json":{"short":"Liest JSON-Text in ein <code>JsonDocument</code>, in dem du Dinge nachschlagen kannst.","simple":"Einen Brief öffnen und seinen Inhalt in die beschrifteten Mappen sortieren.","deep":"Gibt einen <code>DeserializationError</code> zurück, der wahr ist, wenn etwas schiefging (<code>e.c_str()</code> sagt was). Ein <code>Filter</code> behält nur die Felder, die du brauchst, was bei großen Wetterantworten viel RAM spart."},"async-web-server":{"short":"Ein Webserver auf dem Board: Dein Handy oder Laptop öffnet eine Seite oder API, und das Board antwortet.","simple":"Ein winziges Schaufenster: Jede Adresse (<code>/api/card</code>) hat einen Verkäufer, der weiß, was er antworten soll.","deep":"ESPAsyncWebServer antwortet in seinem eigenen Netzwerk-Task, also warten Bildschirm und Leser nie. <code>server_.on(path, HTTP_GET, handler)</code> meldet eine Route an; Handler müssen schnell sein und dürfen nicht blockieren, also wird schwere Arbeit an einen anderen Task weitergereicht."},"async-request":{"short":"Eine eingehende Webanfrage: was verlangt wurde und wie man antwortet.","simple":"Der Kunde am Schaufenster: Du liest seine Bestellung und gibst eine Antwort zurück.","deep":"Handler bekommen es als Pointer, daher <code>req-&gt;send(200, \\"application/json\\", body)</code>. <code>hasParam</code>/<code>getParam</code> lesen Query- oder Formularfelder. Jede Anfrage muss genau ein <code>send</code> bekommen."},"async-web-socket":{"short":"Eine lebendige Zwei-Wege-Leitung zum Browser, damit das Board Updates schicken kann, sobald etwas passiert.","simple":"Ein Telefonat statt Briefen: Die Leitung bleibt offen, und jede Seite kann jederzeit sprechen.","deep":"Am Webserver unter einem Pfad wie <code>/ws</code> eingehängt. <code>textAll</code> sendet an jeden verbundenen Browser; <code>onEvent</code> hört Verbindungen, Trennungen und Nachrichten. Ruf ab und zu <code>cleanupClients()</code> auf, um weggegangene Verbindungen zu entfernen."},"nimble-device":{"short":"Die Eingangstür zu Bluetooth LE: startet den Funkstack und gibt Server, Scanner und Clients aus.","simple":"Die Bluetooth-Rezeption: Sag einmal mit <code>init</code> hallo, dann frag sie nach allem, was du brauchst.","deep":"NimBLE-Arduino, ein leichterer BLE-Stack als Bluedroid. Seine Funktionen sind <code>static</code>, werden also als <code>NimBLEDevice::...</code> ohne Objekt aufgerufen. <code>init(name)</code> setzt den beworbenen Namen; <code>setPower</code> setzt die Sendeleistung in dBm."},"nimble-server":{"short":"Die eigene Bluetooth-Speisekarte des Boards: Services gruppieren Characteristics, kleine Werte, die ein Handy lesen, schreiben oder abonnieren kann.","simple":"Eine Pinnwand mit beschrifteten Fächern: Ein Handy kommt, liest das Temperatur-Fach oder pinnt eine Nachricht ins Nachrichten-Fach.","deep":"GATT: Ein Service (eine UUID) hält Characteristics, jede mit einer UUID, Eigenschaften wie <code>READ | WRITE | NOTIFY</code> und einem Wert bis zur MTU. <code>notify()</code> schickt einen neuen Wert an abonnierte Handys, ohne gefragt zu werden."},"nimble-advertising":{"short":"Lässt das Board ein paar Mal pro Sekunde „Ich bin hier!“ rufen, damit Handys es sehen und sich verbinden können.","simple":"Ein Leuchtturm: kurze Blitze in regelmäßigen Abständen, die jeder in der Nähe sehen kann.","deep":"Ein Legacy-Advertising-Paket trägt höchstens 31 Byte (Name, Flags, Service-UUIDs, Herstellerdaten), plus 31 weitere in einer Scan Response."},"nimble-scan":{"short":"Lauscht nach anderen Bluetooth-Geräten, die in der Nähe werben, und meldet jedes gefundene.","simple":"Die Küste nach Leuchtturm-Blitzen absuchen und jeden notieren, den du siehst.","deep":"Jedes <code>NimBLEAdvertisedDevice</code> hat eine Adresse, einen RSSI und eine Payload. Aktives Scannen fragt auch nach Scan Responses. Callbacks laufen im NimBLE-Host-Task, also reich Ergebnisse an <code>loop()</code> weiter, statt dort zu zeichnen."},"nimble-client":{"short":"Das Board als Besucher: verbindet sich mit einem anderen Bluetooth-Gerät und liest oder schreibt dessen Werte.","simple":"Zur Pinnwand von jemand anderem gehen, statt eine eigene aufzuhängen.","deep":"Die Central-Rolle. Verbinden, Services entdecken (<code>getServices(true)</code>), dann entfernte Characteristics lesen, schreiben oder abonnieren. Verbinden und Entdecken blockieren, also macht B8 sie in einem Worker-Task."},"nimble-conn-info":{"short":"Details einer Bluetooth-Verbindung: wer verbunden ist, wie sie gesichert ist, wie groß ein Paket sein kann.","simple":"Der Besucherausweis: Name, ob ein Ausweis gezeigt wurde und wie viel man auf einmal tragen kann.","deep":"Wird an Callbacks wie <code>onConnect</code> und <code>onAuthenticationComplete</code> übergeben: Adresse des Gegenübers, Connection-Handle, MTU und ob die Verbindung verschlüsselt, authentifiziert und gebondet ist."},"nimble-callbacks":{"short":"Klassen, von denen du erbst, um von Bluetooth-Events zu hören: Verbindungen, Trennungen, Schreib- und Lesezugriffe.","simple":"Deine Telefonnummer an der Rezeption hinterlassen: „Ruf mich an, wenn jemand ankommt.“","deep":"Überschreib nur die <code>virtual</code>-Funktionen, die du brauchst (<code>onConnect</code>, <code>onWrite</code>...), und melde das Objekt dann mit <code>setCallbacks</code> an. Sie laufen im NimBLE-Host-Task, also halt sie kurz und threadsicher."},"nimble-security":{"short":"Entscheidet, wie eine Bluetooth-Verbindung gesichert ist: Pairing, Passkeys und gemerkte Bonds.","simple":"Die Türpolitik: jeden reinlassen, nach einem Code fragen oder nur Freunde reinlassen, die du schon kennst.","deep":"<code>setSecurityAuth(bond, mitm, sc)</code> verlangt Bonding, Man-in-the-Middle-Schutz und LE Secure Connections; die IO-Capability entscheidet, ob ein Passkey oder ein Ja/Nein-Vergleich gezeigt wird. Bonds liegen in NVS und überleben Neustarts."},"ble-note":{"short":"Die Abkürzung dieses Projekts, um dem Aktivitätslog der Bluetooth-Labs eine Zeile hinzuzufügen.","simple":"Eine kurze Notiz im Labortagebuch, die Bildschirm und serielles Log beide zeigen.","deep":"Ein Makro aus <code>kit/lib/ble-kit/src/ble_link.h</code>, das zu <code>::ble::activity().add(::ble::Act::kind, ...)</code> expandiert: ein Eintrag im printf-Stil in einem Ringpuffer, der von einer kritischen Sektion geschützt wird, sodass Callbacks im NimBLE-Task sicher schreiben können."},"i2s-channel":{"short":"Richtet einen I2S-Soundkanal zu einem digitalen Mikrofon oder Lautsprecherverstärker ein.","simple":"Ein Fließband für Sound legen: Ein Takt hält den Rhythmus, und für jeden Sample fährt eine Zahl mit.","deep":"Der I2S-Treiber von ESP-IDF 5: <code>i2s_new_channel</code> erzeugt TX- und/oder RX-Kanäle, <code>i2s_channel_init_std_mode</code> setzt Samplerate, Bitbreite und Pins (Standard-Philips-I2S-Format), <code>i2s_channel_enable</code> startet Takte und DMA."},"i2s-read-write":{"short":"Holt Samples vom Mikrofon oder reicht Samples an den Lautsprecher, durch den I2S-Kanal.","simple":"Pakete vom Fließband nehmen oder darauflegen.","deep":"<code>i2s_channel_read(handle, buf, bytes, &amp;got, timeoutMs)</code> kopiert aus den DMA-Puffern und wartet, wenn keine bereit sind. Schreiben wartet, solange das DMA voll ist, also läuft ein Lautsprecher-Task genau so schnell, wie der Sound spielt."}}`),topics:{basics:{title:`Bausteine`,blurb:`Die kleinen Symbole, die in jeder Zeile rechnen, vergleichen und entscheiden.`},types:{title:`Arten von Werten`,blurb:`Ganze Zahlen, Dezimalzahlen, Text und Ja/Nein: was jede Kiste halten kann.`},flow:{title:`Entscheiden & Wiederholen`,blurb:`Wie der Code einen Weg wählt, Schleifen läuft und eine Aufgabe beendet.`},functions:{title:`Funktionen`,blurb:`Benannte Rezepte, die der Code ausführen kann, von setup() und loop() bis zu winzigen Lambdas.`},memory:{title:`Speicher & const`,blurb:`Wo Werte leben, wie du auf sie zeigst und wie du sie vor Änderung schützt.`},classes:{title:`Typen zum Selbstbauen`,blurb:`Structs, Klassen, Enums und Namespaces: deine eigenen Arten von Dingen.`},modern:{title:`Modernes C++`,blurb:`Konstanten zur Kompilierzeit, Templates, Casts und die Helfer der Standardbibliothek.`},preprocessor:{title:`Vor dem Kompilieren`,blurb:`Zeilen, die mit # beginnen und den Code umbauen, bevor der Compiler ihn liest.`},arduino:{title:`Arduino-Grundlagen`,blurb:`Pins, Timing, serielle Ausgabe und Text: das alltägliche Arduino-Werkzeug.`},esp:{title:`Der ESP32-Chip`,blurb:`Logging, Speicher, Timer und Ablage, die für diesen Chip besonders sind.`},rtos:{title:`Zwei Dinge gleichzeitig tun`,blurb:`FreeRTOS-Tasks, Queues und Locks, mit denen das Board sicher multitaskt.`},libraries:{title:`Bibliotheken`,blurb:`Die Helfer für Bildschirm, WLAN, Webserver, JSON, Bluetooth und Sound, die die Labs nutzen.`}}};export{e as default};
